insert into public.pilares_cfg(n, nombre, bloque, peso, ejes) values
  (1, 'Gobierno y rol de TI', 'A', 10, array['Apoyo al negocio']::text[]),
  (2, 'Valor de negocio y portafolio', 'A', 14, array['Apoyo al negocio']::text[]),
  (3, 'Finanzas y economía unitaria', 'A', 10, array['Eficiencia']::text[]),
  (4, 'Modelo operativo y entrega', 'B', 10, array['Productividad']::text[]),
  (5, 'Operación y servicio', 'B', 9, array['Productividad', 'Eficiencia']::text[]),
  (6, 'Resiliencia y continuidad', 'C', 8, array['Resiliencia']::text[]),
  (7, 'Seguridad y riesgo', 'C', 9, array['Resiliencia']::text[]),
  (8, 'Arquitectura, datos e infraestructura', 'D', 8, array['Innovación y futuro']::text[]),
  (9, 'Talento, organización y proveedores', 'D', 6, array['Eficiencia']::text[]),
  (10, 'Adopción, cultura y gestión del cambio', 'D', 8, array['Productividad', 'Apoyo al negocio']::text[]),
  (11, 'Innovación e IA', 'D', 8, array['Innovación y futuro', 'Apoyo al negocio']::text[])
insert into public.preguntas(id, grupo, orden, enunciado, opciones) values
  ('q001', 1, 1, 'El nuevo accionista pide, para mañana, el documento que explique hacia dónde va la tecnología de la empresa. ¿Qué se le entrega realmente?', '[{"id": "a", "texto": "Un plan anual aprobado el año pasado, archivado, que casi nadie del negocio ha leído."}, {"id": "b", "texto": "Una presentación de hace tiempo, sin fecha clara ni aprobación, que solo conoce el responsable de TI."}, {"id": "c", "texto": "Un plan vigente cuyas revisiones recientes están documentadas con los eventos del negocio que las motivaron."}, {"id": "d", "texto": "No hay nada escrito, se arma una presentación de urgencia con lo que recuerde el responsable."}, {"id": "e", "texto": "Un plan aprobado y vigente, derivado del plan del negocio, con fecha de revisión programada."}]'::jsonb),
  ('q002', 1, 2, 'La gerencia general fija una meta nueva de ventas para el próximo año. ¿Qué pasa en TI a partir de ese anuncio?', '[{"id": "a", "texto": "Se traduce la meta en iniciativas en una sesión con el negocio, y un directivo valida la lista."}, {"id": "b", "texto": "Se reúnen con algunas áreas y arman una lista de proyectos, sin que nadie del negocio la confirme."}, {"id": "c", "texto": "Existe un mecanismo fijo que recalcula las iniciativas cuando cambia una meta, y se ve qué iniciativa responde a qué meta."}, {"id": "d", "texto": "Nada hasta que algún área hace un pedido concreto."}, {"id": "e", "texto": "El responsable de TI decide por su cuenta qué proyectos podrían ayudar, sin consultar a nadie."}]'::jsonb),
  ('q003', 1, 3, 'Se toma al azar diez iniciativas de TI en marcha y se pregunta a cada dueño qué meta del negocio sirven. ¿Qué se encuentra?', '[{"id": "a", "texto": "Cerca de la mitad tiene una meta asociada, pero no siempre está escrita."}, {"id": "b", "texto": "Casi ninguno puede nombrar una meta concreta."}, {"id": "c", "texto": "Todas, con la meta registrada y revisada en el último periodo."}, {"id": "d", "texto": "La gran mayoría tiene meta documentada en el portafolio."}, {"id": "e", "texto": "Unas pocas, y las respuestas dependen de quién conteste."}]'::jsonb),
  ('q004', 1, 4, 'Se detiene en el pasillo a tres gerentes de áreas diferentes y se les pide que digan en qué está trabajando TI este año y por qué. ¿Qué responden?', '[{"id": "a", "texto": "No saben, o mencionan cosas que TI ni siquiera tiene en agenda."}, {"id": "b", "texto": "Cada uno menciona algo distinto, casi siempre lo que le afecta a su área."}, {"id": "c", "texto": "Dos de tres acierta en parte, con descripciones vagas."}, {"id": "d", "texto": "Los tres nombran prioridades que coinciden con las de TI y explican por qué importan."}, {"id": "e", "texto": "Los tres las nombran y las conectan con sus propias metas sin que se les induzca."}]'::jsonb),
  ('q005', 1, 5, 'Hace un año la empresa abrió un mercado nuevo, compró una operación o cambió de modelo. ¿Cómo se refleja eso en lo que TI hace hoy?', '[{"id": "a", "texto": "Cada evento relevante dispara una revisión registrada del plan, con resultado verificable en lo ejecutado."}, {"id": "b", "texto": "Hubo ajustes sueltos que nadie documentó."}, {"id": "c", "texto": "No se refleja, TI sigue con lo mismo de antes."}, {"id": "d", "texto": "Los cambios del plan están fechados y enlazados al evento del negocio que los motivó."}, {"id": "e", "texto": "Hubo cambios en el plan, aunque no queda claro cuál evento los provocó."}]'::jsonb),
  ('q006', 1, 6, 'Una decisión de tecnología se discutió en una reunión hace tres meses y hoy dos personas la recuerdan distinto. ¿Dónde se puede comprobar qué se acordó?', '[{"id": "a", "texto": "En actas de un comité de TI, aunque el negocio rara vez asiste."}, {"id": "b", "texto": "En correos o chats dispersos, si alguien los conserva."}, {"id": "c", "texto": "En ninguna parte, esas decisiones se toman en conversaciones sueltas."}, {"id": "d", "texto": "En actas con seguimiento de acuerdos, donde se ve el cumplimiento y qué se decidió dejar de hacer."}, {"id": "e", "texto": "En actas de un foro periódico con participación habitual de áreas del negocio."}]'::jsonb),
  ('q007', 1, 7, 'Ventas y Finanzas piden lo mismo, el mismo mes, al mismo equipo, y no alcanza para ambos. ¿Cómo se resuelve?', '[{"id": "a", "texto": "Se aplican criterios escritos y medibles, y luego se revisa si la decisión produjo el resultado esperado."}, {"id": "b", "texto": "Un foro decide con criterios acordados, y esos criterios están escritos."}, {"id": "c", "texto": "El responsable de TI elige según su criterio del momento."}, {"id": "d", "texto": "Se conversa entre las áreas y se llega a un acuerdo informal cada vez."}, {"id": "e", "texto": "Gana quien insiste más o quien tiene más jerarquía."}]'::jsonb),
  ('q008', 1, 8, 'Hay que elegir entre dos proveedores de un servicio crítico y nadie quiere ser el que firme. ¿Qué dice la organización sobre quién tiene la última palabra?', '[{"id": "a", "texto": "Se sobreentiende por costumbre, pero no hay nada escrito."}, {"id": "b", "texto": "La matriz se aplica, se revisa con regularidad y hay ejemplos recientes de decisiones donde se siguió."}, {"id": "c", "texto": "No está definido, se discute hasta que alguien cede."}, {"id": "d", "texto": "Hay un documento antiguo que cubre algunas decisiones y no se consulta."}, {"id": "e", "texto": "Existe una matriz vigente que cubre inversión, proveedores, seguridad y datos, y se usa."}]'::jsonb),
  ('q009', 1, 9, 'Un gerente de área necesitaba una herramienta rápido y la contrató con su tarjeta. ¿Cómo se enteró TI y qué pasó después?', '[{"id": "a", "texto": "Hay un proceso que obliga a avisar, y casi siempre se cumple, con algunas excepciones."}, {"id": "b", "texto": "Se enteró meses después por casualidad, y no hay forma de saber cuántos casos hay."}, {"id": "c", "texto": "Se detecta con revisión de gastos y se regulariza con TI en un plazo definido, con casos recientes documentados."}, {"id": "d", "texto": "TI no se enteró, ni suele enterarse de casos así."}, {"id": "e", "texto": "Se enteró porque hubo que integrarla o pagar la factura, y se tolera."}]'::jsonb),
  ('q010', 1, 10, 'Mañana hay reunión de la gerencia general y TI tiene un espacio. ¿Qué es lo que habitualmente se lleva?', '[{"id": "a", "texto": "Un informe periódico con proyectos y tickets, sin vínculo claro con las metas."}, {"id": "b", "texto": "Un informe de frecuencia fija con avance de la estrategia, riesgos y presupuesto."}, {"id": "c", "texto": "Un resumen verbal de lo que se hizo, sin cifras."}, {"id": "d", "texto": "Un informe fijo con datos del periodo, tendencias y decisiones que se le piden a la gerencia."}, {"id": "e", "texto": "No hay espacio fijo, TI informa cuando algo falla."}]'::jsonb),
  ('q011', 1, 11, 'Se organiza la reunión mensual donde la gerencia revisa el negocio. ¿Qué lugar ocupa el responsable de TI?', '[{"id": "a", "texto": "Es miembro fijo, su opinión modifica decisiones del negocio y hay casos recientes que lo demuestran."}, {"id": "b", "texto": "Se le invita a ratos, cuando el tema es técnico."}, {"id": "c", "texto": "Es miembro fijo del comité y reporta a la gerencia general."}, {"id": "d", "texto": "No se le invita, se le consulta si surge una falla."}, {"id": "e", "texto": "Asiste con regularidad, pero reporta a un nivel intermedio y no vota decisiones."}]'::jsonb),
  ('q012', 1, 12, 'En una reunión de recorte de gastos alguien dice ''recortemos en tecnología''. ¿Qué reacción provoca?', '[{"id": "a", "texto": "Los recortes se evalúan contra el valor generado y la gerencia reconoce a TI como parte de los resultados."}, {"id": "b", "texto": "Algunos protestan, pero sin datos que respalden su postura."}, {"id": "c", "texto": "Alguien trae datos de lo que TI aporta y se decide con ellos."}, {"id": "d", "texto": "Nadie la cuestiona, se da por hecho que es gasto puro."}, {"id": "e", "texto": "Se discute y se protege lo que mantiene la operación, sin hablar de valor."}]'::jsonb),
  ('q013', 1, 13, 'La empresa empieza a construir su plan de los próximos tres años. ¿En qué momento aparece TI?', '[{"id": "a", "texto": "Cuando se le pide estimar un costo de algo ya decidido."}, {"id": "b", "texto": "Está desde el inicio y ha propuesto líneas del plan que se adoptaron y dieron resultado."}, {"id": "c", "texto": "Se le consulta en un punto intermedio, sin poder cambiar el plan."}, {"id": "d", "texto": "Cuando el plan ya está cerrado, para ejecutarlo."}, {"id": "e", "texto": "Está desde el inicio y su análisis cambia partes del plan."}]'::jsonb),
  ('q014', 1, 14, 'Se revisa cómo se evalúa el desempeño del responsable de TI a fin de año. ¿En qué se basa?', '[{"id": "a", "texto": "En lo percibido por su jefe, sin indicadores fijos."}, {"id": "b", "texto": "En resultados del negocio que TI influye, medidos con datos y acordados desde el inicio del año."}, {"id": "c", "texto": "No tiene metas formales."}, {"id": "d", "texto": "En indicadores técnicos como disponibilidad o tickets cerrados."}, {"id": "e", "texto": "En una mezcla de indicadores técnicos y algunos de negocio."}]'::jsonb),
  ('q015', 1, 15, 'Se pregunta a la gerencia por una idea nueva de negocio que haya nacido en el equipo de tecnología en los últimos dos años. ¿Qué responden?', '[{"id": "a", "texto": "No recuerdan ninguna, TI solo ejecuta pedidos."}, {"id": "b", "texto": "Mencionan una idea pequeña que no prosperó."}, {"id": "c", "texto": "Citan una iniciativa de negocio propuesta por TI y puesta en marcha."}, {"id": "d", "texto": "Citan varias, con resultados medidos y reconocidos por el negocio."}, {"id": "e", "texto": "Citan alguna mejora interna que propuso TI, sin impacto externo."}]'::jsonb),
  ('q016', 1, 16, 'Un empleado nuevo pregunta qué puede y qué no puede hacer con los equipos, los datos y las herramientas de IA. ¿Qué se le entrega?', '[{"id": "a", "texto": "Nada, se le explica de palabra lo básico."}, {"id": "b", "texto": "Políticas vigentes con revisión periódica registrada y constancia de que el personal las recibió."}, {"id": "c", "texto": "Un documento viejo, sin fecha y sin que se sepa si sigue vigente."}, {"id": "d", "texto": "Políticas aprobadas para algunos temas, con otras ausentes o desactualizadas."}, {"id": "e", "texto": "Políticas aprobadas, fechadas y vigentes para los temas principales, incluida la IA."}]'::jsonb),
  ('q017', 1, 17, 'Aparece una nueva regulación que podría afectar cómo se manejan los datos. ¿Quién se entera y qué hace?', '[{"id": "a", "texto": "Alguien de TI la ve casualmente en las noticias."}, {"id": "b", "texto": "Nadie la sigue, se sabría solo por una multa o un reclamo."}, {"id": "c", "texto": "Legal la monitorea, pero TI se entera tarde."}, {"id": "d", "texto": "Hay un proceso fijo de seguimiento con evaluaciones de impacto registradas en cada cambio normativo."}, {"id": "e", "texto": "Hay un responsable designado que avisa a TI y al negocio y se evalúa el impacto."}]'::jsonb),
  ('q018', 1, 18, 'Se revisa el informe de la última auditoría que tocó a TI. ¿Qué pasó con lo que se encontró?', '[{"id": "a", "texto": "No hubo auditorías, o no se conserva el informe."}, {"id": "b", "texto": "Los hallazgos se cierran en plazo, con verificación independiente de los cierres y menos repetidos cada vez."}, {"id": "c", "texto": "Hubo informe, pero nadie dio seguimiento a los hallazgos."}, {"id": "d", "texto": "Algunos hallazgos se atendieron, sin registro de plazos ni responsables."}, {"id": "e", "texto": "Los hallazgos tienen responsable y plan, y la mayoría se cerró en el plazo."}]'::jsonb),
  ('q019', 1, 19, 'Se pregunta cuántas de las políticas de TI se verifican realmente, y no solo se firman. ¿Qué se descubre?', '[{"id": "a", "texto": "Se verifica alguna a pedido, sin regularidad."}, {"id": "b", "texto": "Ninguna se verifica."}, {"id": "c", "texto": "Se verifican casi todas con datos del periodo, y los incumplimientos generan acciones correctivas."}, {"id": "d", "texto": "Se verifican algunas políticas clave, pero no se conoce el nivel de cumplimiento."}, {"id": "e", "texto": "Se verifica la mayoría y se conoce un nivel de cumplimiento aproximado."}]'::jsonb),
  ('q020', 2, 1, 'El gerente general pregunta: ''dime todo lo que TI está construyendo ahora mismo y para quién''. ¿Cómo se responde?', '[{"id": "a", "texto": "Con una hoja de proyectos con presupuesto y fechas, sin dueño de negocio en todos."}, {"id": "b", "texto": "Con una lista armada de memoria que seguramente omite proyectos."}, {"id": "c", "texto": "Con un inventario único, actualizado, que además se usa para decidir qué entra y qué se detiene."}, {"id": "d", "texto": "Con un inventario único que muestra dueño, presupuesto, fechas y estado de cada uno."}, {"id": "e", "texto": "No se puede responder sin preguntar uno por uno a cada persona."}]'::jsonb),
  ('q021', 2, 2, 'Llega un proyecto nuevo y urgente. El responsable de TI debe decir si cabe en el equipo. ¿Con qué base responde?', '[{"id": "a", "texto": "Con un conteo de proyectos activos, sin saber cuánto tiempo disponible hay."}, {"id": "b", "texto": "Con la carga y la capacidad medidas por equipo, y se dice qué se pospone."}, {"id": "c", "texto": "Con su impresión de cómo anda la gente esta semana."}, {"id": "d", "texto": "Con datos de capacidad actualizados, y la decisión se compara con lo que realmente pasó en casos anteriores."}, {"id": "e", "texto": "Con un ''sí'' por compromiso, aunque el equipo ya esté desbordado."}]'::jsonb),
  ('q022', 2, 3, 'Hay diez proyectos que querrían empezar y solo hay recursos para cuatro. ¿Cómo se elige cuáles?', '[{"id": "a", "texto": "Los que pida el más influyente."}, {"id": "b", "texto": "Con criterios escritos, y luego se revisa si los proyectos elegidos dieron mejores resultados que los descartados."}, {"id": "c", "texto": "Por conversación entre gerentes, sin una regla fija."}, {"id": "d", "texto": "Con criterios escritos y ponderados, aprobados por un comité."}, {"id": "e", "texto": "Los que el responsable de TI considere más importantes."}]'::jsonb),
  ('q023', 2, 4, 'Se pregunta por el último proyecto que se decidió detener antes de terminarlo. ¿Qué se cuenta?', '[{"id": "a", "texto": "Se detuvieron proyectos con una decisión y un criterio acordado, y quedó registrada la causa."}, {"id": "b", "texto": "Alguno murió por falta de interés, sin una decisión explícita."}, {"id": "c", "texto": "Detener proyectos es una práctica normal con criterios claros, y lo aprendido cambió cómo se aprueban los nuevos."}, {"id": "d", "texto": "No se recuerda ninguno, los proyectos nunca se detienen aunque estén mal."}, {"id": "e", "texto": "Se detuvo alguno por falta de presupuesto, sin análisis de por qué."}]'::jsonb),
  ('q024', 2, 5, 'Si se pudiera mirar el calendario de todo el equipo de TI durante un mes, ¿qué se vería?', '[{"id": "a", "texto": "Predomina el mantenimiento, con unas pocas horas sueltas para mejoras."}, {"id": "b", "texto": "Se mide, se compara mes a mes y se ajusta para sostener una parte relevante en trabajo nuevo de valor."}, {"id": "c", "texto": "Se mide la distribución y hay un espacio protegido para mejorar y crear."}, {"id": "d", "texto": "Casi todo el tiempo apagando incendios y manteniendo lo existente."}, {"id": "e", "texto": "Se sabe a grandes rasgos, pero no se mide en horas."}]'::jsonb),
  ('q025', 2, 6, 'Se escoge un proyecto grande aprobado el año pasado y se pide ver por qué se aprobó. ¿Qué aparece?', '[{"id": "a", "texto": "Un documento con costos claros y beneficios descritos sin cifras."}, {"id": "b", "texto": "Una presentación con ideas generales de lo que mejoraría."}, {"id": "c", "texto": "Un caso de negocio con beneficios cuantificados y un responsable nombrado."}, {"id": "d", "texto": "Ningún documento, se aprobó porque se consideró necesario."}, {"id": "e", "texto": "Un caso de negocio cuantificado que se actualizó durante la ejecución y se usó para decidir seguir."}]'::jsonb),
  ('q026', 2, 7, 'Se leen cinco justificaciones de proyectos y se anota qué prometen lograr. ¿Qué patrón aparece?', '[{"id": "a", "texto": "Cada una declara con claridad un tipo de beneficio y cómo se notaría."}, {"id": "b", "texto": "Mezclan promesas de distinto tipo sin separarlas ni medirlas."}, {"id": "c", "texto": "Frases como ''mejorar la eficiencia'' sin decir en qué."}, {"id": "d", "texto": "Cada una declara tipo, cifra y forma de medirlo, y el tipo coincide con lo que luego se midió."}, {"id": "e", "texto": "No prometen nada concreto."}]'::jsonb),
  ('q027', 2, 8, 'Un proyecto termina y no aparece el ahorro prometido. ¿A quién se le pregunta por qué?', '[{"id": "a", "texto": "Al dueño del beneficio, cuyo cumplimiento forma parte de sus metas de desempeño."}, {"id": "b", "texto": "No está claro, cada uno cree que le correspondía a otro."}, {"id": "c", "texto": "Al sponsor que lo pidió, aunque no había compromiso escrito."}, {"id": "d", "texto": "A TI, porque nadie más se sintió responsable."}, {"id": "e", "texto": "Al dueño del beneficio, que firmó el compromiso al aprobarse el proyecto."}]'::jsonb),
  ('q028', 2, 9, 'Un caso de negocio decía ''esto reducirá el tiempo de proceso a la mitad''. Seis meses después, ¿qué se hizo con esa afirmación?', '[{"id": "a", "texto": "Se comparó con datos reales y se documentó la diferencia."}, {"id": "b", "texto": "Alguien comentó de pasada que ''parece que ayudó''."}, {"id": "c", "texto": "Se revisó en una reunión, pero sin datos."}, {"id": "d", "texto": "Se comparó con datos, se explicó la diferencia y esos aprendizajes se aplicaron a los siguientes casos."}, {"id": "e", "texto": "Nada, nadie volvió a mirarla."}]'::jsonb),
  ('q029', 2, 10, 'Se toman todos los proyectos cerrados en los últimos dos años y se busca el informe de qué lograron realmente. ¿Qué se encuentra?', '[{"id": "a", "texto": "Ningún informe de resultados."}, {"id": "b", "texto": "Informes de algunos proyectos grandes, no sistemáticos."}, {"id": "c", "texto": "Informes a 6 y 12 meses para la mayoría de los proyectos."}, {"id": "d", "texto": "Informes a 6 y 12 meses para casi todos, y el comité los usa en nuevas decisiones."}, {"id": "e", "texto": "Unos pocos con comentarios cualitativos."}]'::jsonb),
  ('q030', 2, 11, 'Si se suman todos los beneficios prometidos en los proyectos cerrados y se comparan con lo conseguido, ¿cómo se ve el resultado?', '[{"id": "a", "texto": "Se cree que se logró casi todo, aunque nadie lo verificó."}, {"id": "b", "texto": "Hay una cifra medida para la mayoría y se conocen las razones de las brechas."}, {"id": "c", "texto": "No se puede saber, no hay datos."}, {"id": "d", "texto": "Hay estimaciones de lo logrado en algunos proyectos, con grandes diferencias."}, {"id": "e", "texto": "Hay una cifra medida, confirmada por Finanzas, y los resultados están en mejora respecto del periodo anterior."}]'::jsonb),
  ('q031', 2, 12, 'Alguien dice: ''ese proyecto se entregó perfecto, a tiempo y en presupuesto''. ¿Qué pregunta le sigue?', '[{"id": "a", "texto": "Se reconoce que algunos casos quedaron sin beneficio visible, sin tener una lista."}, {"id": "b", "texto": "Existe una lista revisada de proyectos así, con causa raíz y ajustes al proceso de aprobación."}, {"id": "c", "texto": "Se identifican esos casos, se discuten con el negocio y se anota qué falló."}, {"id": "d", "texto": "''¿Y lo usan?'', pero nadie sabe responder."}, {"id": "e", "texto": "Ninguna, con eso se considera exitoso."}]'::jsonb),
  ('q032', 2, 13, 'Un beneficio prometido no se materializa. ¿Qué consecuencia tiene eso?', '[{"id": "a", "texto": "Se audita con regularidad, se ajusta el portafolio y los resultados influyen en futuras aprobaciones."}, {"id": "b", "texto": "Un comentario incómodo en alguna reunión."}, {"id": "c", "texto": "Se revisa el caso, pero sin responsable ni consecuencia clara."}, {"id": "d", "texto": "Finanzas o una instancia independiente lo revisa, y se define un plan correctivo."}, {"id": "e", "texto": "Ninguna, se sigue adelante."}]'::jsonb),
  ('q033', 2, 14, 'Se pide la lista de todas las aplicaciones que la empresa paga o usa. ¿Qué se entrega?', '[{"id": "a", "texto": "Una lista con costos y responsables técnicos, sin usuarios ni fechas de fin de vida."}, {"id": "b", "texto": "Una lista parcial, sin costos ni dueños."}, {"id": "c", "texto": "No existe, hay que reconstruirla preguntando a todos."}, {"id": "d", "texto": "Un inventario completo con dueño de negocio, usuarios, costo y fecha de fin de vida."}, {"id": "e", "texto": "Un inventario actualizado y consultado en decisiones de compra, renovación y retiro."}]'::jsonb),
  ('q034', 2, 15, 'Un área pide una aplicación nueva para una tarea. ¿Cómo se verifica si algo parecido ya existe?', '[{"id": "a", "texto": "Se mide uso periódicamente, se detectan duplicidades y se retiran activamente las aplicaciones sobrantes."}, {"id": "b", "texto": "No se verifica, se compra."}, {"id": "c", "texto": "Se pregunta de palabra a quien parezca saber."}, {"id": "d", "texto": "Se revisa una lista, pero está desactualizada."}, {"id": "e", "texto": "Se consulta el inventario y se mide si hay duplicidad o uso bajo."}]'::jsonb),
  ('q035', 2, 16, 'El fabricante de un sistema crítico anuncia que deja de dar soporte el próximo año. ¿Qué pasa en la empresa?', '[{"id": "a", "texto": "El registro se revisa cada trimestre, y los sistemas críticos fuera de soporte se reducen de forma comprobable."}, {"id": "b", "texto": "Hay un registro de sistemas fuera de soporte, con plan, fecha y presupuesto."}, {"id": "c", "texto": "Se conoce el caso, pero sin plan."}, {"id": "d", "texto": "Se conoce y hay un plan general sin fecha ni presupuesto."}, {"id": "e", "texto": "Nadie lo había notado, ni se sabe cuántos sistemas están en esa situación."}]'::jsonb),
  ('q036', 2, 17, 'Alguien afirma que ''apagar sistemas viejos ahorra dinero''. ¿Qué evidencia hay en la empresa?', '[{"id": "a", "texto": "Se apagó alguno sin saber cuánto se ahorró."}, {"id": "b", "texto": "Hay un programa de retiro continuo con ahorros verificados por Finanzas."}, {"id": "c", "texto": "Ningún sistema se ha apagado nunca."}, {"id": "d", "texto": "Se retiraron algunos, con una idea aproximada del ahorro."}, {"id": "e", "texto": "Se retiraron sistemas con un ahorro documentado por cada uno."}]'::jsonb),
  ('q037', 2, 18, '¿Cómo se entera TI de lo que las áreas del negocio realmente piensan de su servicio?', '[{"id": "a", "texto": "Con alguna encuesta ocasional, sin seguimiento."}, {"id": "b", "texto": "No se entera, supone que todo va bien si nadie se queja."}, {"id": "c", "texto": "Con mediciones periódicas, comparadas contra el periodo anterior, y con mejoras demostradas."}, {"id": "d", "texto": "Por quejas aisladas o comentarios de pasillo."}, {"id": "e", "texto": "Con una encuesta periódica que genera acciones concretas."}]'::jsonb),
  ('q038', 2, 19, 'Se pregunta a un gerente de negocio qué le gustaría pedirle a TI que hoy no puede. ¿Qué responde?', '[{"id": "a", "texto": "Menciona cosas concretas que ya están en la lista de pendientes de TI."}, {"id": "b", "texto": "Menciona cosas que están en el plan de TI con fecha, y reconoce avances recientes."}, {"id": "c", "texto": "No sabe qué pedir, porque nunca se lo han preguntado."}, {"id": "d", "texto": "Enumera quejas generales, sin esperanza de que algo cambie."}, {"id": "e", "texto": "Menciona dos o tres cosas, aunque aún no se las ha comunicado a TI."}]'::jsonb),
  ('q039', 2, 20, 'Se pregunta a la gerencia comercial y a la de operaciones qué resultado del último año se debe en buena parte a tecnología. ¿Qué responden?', '[{"id": "a", "texto": "Algo genérico como ''ahora tenemos más sistemas''."}, {"id": "b", "texto": "Ejemplos concretos con cifras razonables que ambos pueden explicar."}, {"id": "c", "texto": "Ninguno, para ellos TI es un servicio de soporte."}, {"id": "d", "texto": "Un ejemplo concreto, pero sin cifras."}, {"id": "e", "texto": "Varios resultados cuantificados, reconocidos por Finanzas y presentes en los resultados del negocio."}]'::jsonb),
  ('q040', 3, 1, 'El director financiero pregunta cuánto gasta realmente la empresa en tecnología, sumando todas las áreas. ¿Cuánto tarda en tener una respuesta confiable?', '[{"id": "a", "texto": "Semanas, y la cifra final sería una estimación con muchos huecos."}, {"id": "b", "texto": "Un día, a partir de cuentas contables y registros ya clasificados."}, {"id": "c", "texto": "Minutos, desde un reporte que se actualiza cada mes y Finanzas ya valida."}, {"id": "d", "texto": "No se puede obtener, la información está dispersa y nadie la consolida."}, {"id": "e", "texto": "Unos días, con el presupuesto de TI más lo que Finanzas logre rastrear."}]'::jsonb),
  ('q041', 3, 2, 'Se pide ver en qué se gastó el dinero de tecnología el último trimestre. ¿Cómo viene presentado?', '[{"id": "a", "texto": "Con categorías consistentes que además se comparan con lo planificado y con periodos anteriores."}, {"id": "b", "texto": "Con algunas categorías, mezcladas y poco consistentes."}, {"id": "c", "texto": "Como un total por área, sin detalle de en qué se gastó."}, {"id": "d", "texto": "Con categorías claras y consistentes entre meses."}, {"id": "e", "texto": "Como una lista de facturas sin orden."}]'::jsonb),
  ('q042', 3, 3, 'Se revisan las facturas de software y servicios digitales pagadas por áreas distintas a TI. ¿Qué se encuentra?', '[{"id": "a", "texto": "Se encuentran sorpresas importantes que TI no conocía."}, {"id": "b", "texto": "No se sabe, nadie ha revisado."}, {"id": "c", "texto": "Se mide cada mes, se revisa con Finanzas y se reduce o regulariza con evidencia."}, {"id": "d", "texto": "Hay una parte significativa, con una cifra aproximada."}, {"id": "e", "texto": "Se conoce la cifra, es una parte pequeña y está aprobada formalmente."}]'::jsonb),
  ('q043', 3, 4, 'Un gerente de área quiere saber cuánto cuesta lo que TI le presta. ¿Cómo se le responde?', '[{"id": "a", "texto": "Con costo por servicio y por área consumidora, trazable al libro contable y revisado por Finanzas."}, {"id": "b", "texto": "Con una estimación gruesa y sin sustento."}, {"id": "c", "texto": "Con una asignación por servicio, que se reconcilia con el libro contable."}, {"id": "d", "texto": "Con un reparto por porcentaje fijo, sin relación con el uso real."}, {"id": "e", "texto": "No se puede, solo se le dice que TI es un costo corporativo."}]'::jsonb),
  ('q044', 3, 5, 'Se compara lo que se presupuestó de tecnología con lo que se gastó en cada uno de los últimos tres años. ¿Qué muestra?', '[{"id": "a", "texto": "Desviaciones pequeñas y estables, con un pronóstico que anticipa los cambios."}, {"id": "b", "texto": "Desviaciones pequeñas en general, explicadas en el momento por categoría."}, {"id": "c", "texto": "No existe presupuesto formal, o no se conserva."}, {"id": "d", "texto": "Desviaciones notables en algunas categorías, con explicaciones a posteriori."}, {"id": "e", "texto": "Grandes desviaciones en distintos sentidos, sin explicación."}]'::jsonb),
  ('q045', 3, 6, 'Si se dividiera el presupuesto de tecnología entre ''mantener la operación'' y ''construir lo nuevo'', ¿qué proporción aparecería?', '[{"id": "a", "texto": "Se cree que casi todo es operación, pero sin cifras."}, {"id": "b", "texto": "No se ha dividido nunca, no se sabe."}, {"id": "c", "texto": "Hay una división aproximada, que no se revisa."}, {"id": "d", "texto": "Hay una división medida cada año y se discute en el comité."}, {"id": "e", "texto": "Hay una división medida, con meta definida y evidencia de que la proporción de crecimiento mejoró."}]'::jsonb),
  ('q046', 3, 7, 'A mitad de año se pregunta cuánto se espera gastar al cierre. ¿Cómo se responde?', '[{"id": "a", "texto": "No se sabe hasta que llegue el cierre."}, {"id": "b", "texto": "Con la cifra del presupuesto original, sin ajustarla."}, {"id": "c", "texto": "Con un pronóstico actualizado cada trimestre."}, {"id": "d", "texto": "Con una proyección hecha a mano una vez al año."}, {"id": "e", "texto": "Con un pronóstico mensual que incorpora consumo real y que ha mostrado ser preciso."}]'::jsonb),
  ('q047', 3, 8, 'Se pregunta por el último gasto grande que nadie había previsto. ¿Qué se cuenta?', '[{"id": "a", "texto": "Se analizó la causa de los principales y se agregaron controles."}, {"id": "b", "texto": "Hubo varios, sin una explicación clara de por qué."}, {"id": "c", "texto": "Se analizan sistemáticamente las desviaciones y los controles nuevos redujeron su repetición."}, {"id": "d", "texto": "Se conoce el origen de algunos, pero no se tomó acción."}, {"id": "e", "texto": "Se recuerda alguno, atribuido a mala suerte."}]'::jsonb),
  ('q048', 3, 9, 'Se pregunta cuánto cuesta mantener a un empleado con su puesto de trabajo digital, completo. ¿Qué se responde?', '[{"id": "a", "texto": "Un número de memoria, que cambia según quién lo diga."}, {"id": "b", "texto": "No se ha calculado nunca."}, {"id": "c", "texto": "Un cálculo mensual completo, validado por Finanzas y usado para tomar decisiones."}, {"id": "d", "texto": "Un cálculo completo con una metodología conocida."}, {"id": "e", "texto": "Un cálculo aproximado, que omite varios costos."}]'::jsonb),
  ('q049', 3, 10, 'Si se pide ver cómo ha cambiado ese costo por usuario en tres años, ¿qué se puede mostrar?', '[{"id": "a", "texto": "Datos de uno o dos años, no comparables entre sí."}, {"id": "b", "texto": "Una sensación de que subió, sin cifras."}, {"id": "c", "texto": "Una serie comparable con tendencia, causas explicadas y acciones que redujeron el costo sin perder servicio."}, {"id": "d", "texto": "Nada, no hay datos históricos."}, {"id": "e", "texto": "Una serie comparable de tres años, con explicación de los cambios."}]'::jsonb),
  ('q050', 3, 11, 'El directorio pregunta si la empresa gasta más o menos que antes en tecnología respecto de lo que vende. ¿Qué se contesta?', '[{"id": "a", "texto": "No se sabe."}, {"id": "b", "texto": "Se contesta con una impresión general."}, {"id": "c", "texto": "Se contesta con la relación y su evolución en varios años."}, {"id": "d", "texto": "Se contesta con la relación, su evolución y la explicación de qué la movió."}, {"id": "e", "texto": "Se contesta con una cifra del año actual, sin historia."}]'::jsonb),
  ('q051', 3, 12, 'Alguien sospecha que hay servicios caros que casi nadie usa. ¿Cómo se verifica?', '[{"id": "a", "texto": "Cruzando costo y uso de los servicios principales para identificar los de baja relación."}, {"id": "b", "texto": "No se puede, no hay datos de uso ni de costo."}, {"id": "c", "texto": "Con datos de costo y de uso, pero de distintas fuentes y sin cruzarlos."}, {"id": "d", "texto": "Preguntando a la gente, sin datos."}, {"id": "e", "texto": "Con un cruce regular que ha llevado a retirar o renegociar servicios con resultados medidos."}]'::jsonb),
  ('q052', 3, 13, 'Un contrato de software se renovó automáticamente por un año más y nadie lo notó. ¿Cómo se evita que vuelva a pasar?', '[{"id": "a", "texto": "No se evita, ocurre con frecuencia."}, {"id": "b", "texto": "Alguien tiene en la cabeza algunas fechas."}, {"id": "c", "texto": "Hay un inventario con vencimientos, renovaciones y penalidades, con alertas."}, {"id": "d", "texto": "Hay una hoja con vencimientos, desactualizada."}, {"id": "e", "texto": "Hay inventario, alertas y un proceso de renegociación anticipada con resultados documentados."}]'::jsonb),
  ('q053', 3, 14, 'Se compara el número de licencias pagadas con el número de personas que realmente las usan. ¿Qué se ve?', '[{"id": "a", "texto": "No se sabe cuántas licencias hay."}, {"id": "b", "texto": "Se sabe en los sistemas principales y hay un desperdicio notable."}, {"id": "c", "texto": "Se mide el uso, se reasigna y el desperdicio se redujo de forma comprobada."}, {"id": "d", "texto": "Se mide el uso con regularidad y se reasignan las licencias sin uso."}, {"id": "e", "texto": "Se sabe cuántas hay, pero no quién las usa."}]'::jsonb),
  ('q054', 3, 15, 'A fin de mes llega una factura de nube mucho mayor de lo habitual. ¿Qué pasa?', '[{"id": "a", "texto": "Sorpresa y revisión manual de quién causó el aumento."}, {"id": "b", "texto": "Hay presupuestos por equipo, alertas y revisiones periódicas que bajaron el costo de forma medida."}, {"id": "c", "texto": "Alguien pregunta en el equipo hasta dar con el responsable."}, {"id": "d", "texto": "Se descubre la causa con esfuerzo, gracias a etiquetas en parte de los recursos."}, {"id": "e", "texto": "Habría saltado una alerta antes, y los recursos están etiquetados por dueño."}]'::jsonb),
  ('q055', 3, 16, 'Se pregunta cuándo fue la última vez que se renegoció con un proveedor grande y qué se consiguió. ¿Qué se responde?', '[{"id": "a", "texto": "Existe un calendario de renegociaciones, y los ahorros fueron verificados por Finanzas."}, {"id": "b", "texto": "Nunca se renegocia, se acepta el aumento."}, {"id": "c", "texto": "Se renegoció algún contrato con un ahorro estimado."}, {"id": "d", "texto": "Se renegociaron los principales, con ahorros documentados."}, {"id": "e", "texto": "Se intentó una vez sin éxito claro."}]'::jsonb),
  ('q056', 3, 17, 'Se pregunta cuánto cuesta en total lo que la empresa hace con inteligencia artificial, sumando licencias, consumo y personas. ¿Qué se responde?', '[{"id": "a", "texto": "Se conoce el costo total mes a mes, desglosado por caso de uso y por área."}, {"id": "b", "texto": "No se sabe, el gasto está disperso en tarjetas y áreas."}, {"id": "c", "texto": "Se conoce la mayor parte de licencias, pero no el consumo ni las personas."}, {"id": "d", "texto": "Se conoce el costo total con una categoría propia en el presupuesto."}, {"id": "e", "texto": "Se conoce el costo de una o dos herramientas."}]'::jsonb),
  ('q057', 3, 18, 'Un asistente de IA interno se vuelve popular y su consumo se dispara. ¿Cómo se entera la empresa?', '[{"id": "a", "texto": "Porque se mide el consumo por caso de uso y se revisa cada mes."}, {"id": "b", "texto": "Porque hay un reporte del proveedor, que nadie revisa con regularidad."}, {"id": "c", "texto": "Porque alguien lo comenta, sin cifras."}, {"id": "d", "texto": "Por la factura del proveedor, sin saber qué lo causó."}, {"id": "e", "texto": "Porque se mide el costo por tarea y se usa para decidir si el caso se amplía, se ajusta o se detiene."}]'::jsonb),
  ('q058', 3, 19, 'Alguien deja un proceso automatizado corriendo toda la noche con un servicio de IA que cobra por uso. ¿Qué lo habría frenado?', '[{"id": "a", "texto": "Un tope general del proveedor, sin alertas internas."}, {"id": "b", "texto": "Un presupuesto asignado con alertas al acercarse al límite."}, {"id": "c", "texto": "Alguien lo habría visto por casualidad."}, {"id": "d", "texto": "Presupuestos y topes por caso con alertas, y un historial de que funcionaron al evitar excesos."}, {"id": "e", "texto": "Nada, el cobro habría llegado al final."}]'::jsonb),
  ('q059', 3, 20, 'Alguien en una reunión dice ''la IA nos está ahorrando mucho''. ¿Qué se le pide?', '[{"id": "a", "texto": "Un cálculo con método acordado con Finanzas, comparado con el costo total de la IA."}, {"id": "b", "texto": "Una estimación del ahorro, sin método claro."}, {"id": "c", "texto": "Nada, se acepta como cierto."}, {"id": "d", "texto": "Que dé un ejemplo, aunque no tenga cifras."}, {"id": "e", "texto": "Un cálculo con método definido y datos de antes y después."}]'::jsonb),
  ('q060', 4, 1, 'Termina un proyecto importante. ¿Qué pasa con las personas que lo construyeron?', '[{"id": "a", "texto": "Un equipo estable sigue a cargo del sistema o producto, con su responsable definido."}, {"id": "b", "texto": "El equipo estable evoluciona el producto con prioridades acordadas con el negocio y se miden sus resultados."}, {"id": "c", "texto": "Vuelven a sus funciones y alguien atiende lo que falle, sin responsable claro."}, {"id": "d", "texto": "Pasan a otros proyectos y una persona queda como soporte del sistema."}, {"id": "e", "texto": "Se dispersan y nadie queda a cargo de lo construido."}]'::jsonb),
  ('q061', 4, 2, 'El sistema de facturación necesita un cambio que afecta a tres áreas. ¿Quién decide qué se hace?', '[{"id": "a", "texto": "Hay un dueño de negocio nombrado que decide y prioriza cambios."}, {"id": "b", "texto": "Se discute hasta que alguien cede, no hay una persona responsable."}, {"id": "c", "texto": "TI decide por defecto, porque nadie más lo reclama."}, {"id": "d", "texto": "Hay un dueño de negocio nominal que no participa mucho."}, {"id": "e", "texto": "Hay dueños nombrados que además responden por el uso y los resultados del sistema."}]'::jsonb),
  ('q062', 4, 3, 'Un área necesita una funcionalidad nueva. ¿Cómo se trabaja desde el primer día?', '[{"id": "a", "texto": "El área envía un correo y espera."}, {"id": "b", "texto": "Un equipo conjunto trabaja de forma continua, con prioridades compartidas y resultados revisados juntos."}, {"id": "c", "texto": "Envía un requerimiento escrito y TI responde con una fecha."}, {"id": "d", "texto": "Hay reuniones de arranque y de cierre, y poco contacto en el medio."}, {"id": "e", "texto": "Personas del negocio y de TI trabajan juntas durante buena parte del desarrollo."}]'::jsonb),
  ('q063', 4, 4, 'Una persona de TI se va de vacaciones tres semanas sin posibilidad de contacto. ¿Qué sistemas quedan en riesgo?', '[{"id": "a", "texto": "Todos los críticos tienen más de una persona capacitada, y se ha probado que otra persona puede operarlos."}, {"id": "b", "texto": "Al menos uno crítico, y se confía en que no falle."}, {"id": "c", "texto": "Varios sistemas críticos, y nadie más sabría tocarlos."}, {"id": "d", "texto": "Se conoce cuáles dependen de una persona, sin plan para cubrirlos."}, {"id": "e", "texto": "Los críticos tienen suplente y documentación básica."}]'::jsonb),
  ('q064', 4, 5, 'Se pregunta cuántas veces en el último mes se pusieron mejoras en el sistema principal. ¿Qué se responde?', '[{"id": "a", "texto": "Una vez al mes aproximadamente, con ventanas definidas."}, {"id": "b", "texto": "Pocas veces al año, en grandes paquetes."}, {"id": "c", "texto": "Con frecuencia medida por sistema, y la tendencia es ascendente sin perder estabilidad."}, {"id": "d", "texto": "Varias veces al mes, con cambios pequeños y registrados."}, {"id": "e", "texto": "No se sabe, no hay registro."}]'::jsonb),
  ('q065', 4, 6, 'Un cambio ya probado y aprobado espera salir a producción. ¿Cuánto tiempo pasa hasta que los usuarios lo ven?', '[{"id": "a", "texto": "Horas o un día, con un proceso automatizado."}, {"id": "b", "texto": "Varios días, según la disponibilidad de quien lo despliega."}, {"id": "c", "texto": "Horas, medido sistemáticamente, y esa cifra mejora con el tiempo."}, {"id": "d", "texto": "Unos días, con un proceso conocido pero manual."}, {"id": "e", "texto": "Semanas o meses, y nadie sabe dónde se detiene."}]'::jsonb),
  ('q066', 4, 7, 'Un gerente pide una mejora pequeña a un reporte. ¿Cuánto tarda en tenerla, desde que la pide?', '[{"id": "a", "texto": "Un tiempo medido y comparado entre periodos, con una cola corta y estable."}, {"id": "b", "texto": "Un tiempo predecible que se comunica de antemano."}, {"id": "c", "texto": "Semanas, con un tiempo que varía mucho."}, {"id": "d", "texto": "No se sabe, a veces nunca llega."}, {"id": "e", "texto": "Meses, y depende de a quién se le pida."}]'::jsonb),
  ('q067', 4, 8, 'Se revisa la lista de pedidos pendientes que nadie ha atendido. ¿Qué se encuentra?', '[{"id": "a", "texto": "Una lista larga con pedidos de hace más de un año sin respuesta."}, {"id": "b", "texto": "Una lista visible con antigüedad conocida y revisión periódica."}, {"id": "c", "texto": "Una lista con antigüedad variable y sin criterio para depurarla."}, {"id": "d", "texto": "Una lista corta, con antigüedad medida, que el negocio puede consultar en cualquier momento."}, {"id": "e", "texto": "No hay lista, o es imposible saber qué falta."}]'::jsonb),
  ('q068', 4, 9, 'Después de poner una mejora en producción, ¿con qué frecuencia hay que corregir algo de inmediato?', '[{"id": "a", "texto": "Con frecuencia, y a nadie le sorprende."}, {"id": "b", "texto": "A veces, pero no se lleva la cuenta."}, {"id": "c", "texto": "Se mide y es una proporción baja y controlada."}, {"id": "d", "texto": "Se sabe que pasa en cierta proporción, sin cifra exacta."}, {"id": "e", "texto": "Se mide, es baja, y se vincula cada caso a una causa que se corrige."}]'::jsonb),
  ('q069', 4, 10, 'Un cambio rompe un servicio importante. ¿Cuánto tarda en volver a funcionar?', '[{"id": "a", "texto": "Menos de una jornada, con reversión ensayada."}, {"id": "b", "texto": "Horas o más, con improvisación."}, {"id": "c", "texto": "Varias horas, con un procedimiento conocido pero no ensayado."}, {"id": "d", "texto": "Poco tiempo medido, con reversión rápida y datos que muestran mejora."}, {"id": "e", "texto": "No se sabe, depende del día y de quién esté."}]'::jsonb),
  ('q070', 4, 11, 'Se toma un cambio hecho el mes pasado y se pide la evidencia de que se probó y se aprobó antes de salir. ¿Qué existe?', '[{"id": "a", "texto": "Un registro completo y se verifica periódicamente que todos los cambios lo cumplen."}, {"id": "b", "texto": "Un mensaje en un chat."}, {"id": "c", "texto": "Un registro con pruebas, revisión y aprobación."}, {"id": "d", "texto": "Un registro de aprobación, pero sin pruebas anexas."}, {"id": "e", "texto": "Nada, salió porque alguien lo decidió."}]'::jsonb),
  ('q071', 4, 12, 'Un viernes por la noche hay que hacer un cambio urgente que no puede esperar. ¿Cómo se maneja?', '[{"id": "a", "texto": "Se avisa por mensaje y se hace con lo que haya."}, {"id": "b", "texto": "Quien pueda lo hace, sin aviso."}, {"id": "c", "texto": "Hay un procedimiento, pero casi siempre se salta."}, {"id": "d", "texto": "El procedimiento se cumple, los cambios de emergencia se revisan después y su número ha ido bajando."}, {"id": "e", "texto": "Existe un procedimiento de emergencia con aprobación rápida y registro posterior."}]'::jsonb),
  ('q072', 4, 13, 'Se entregó un sistema nuevo para el proceso de compras. ¿Qué cambió realmente en la forma de comprar?', '[{"id": "a", "texto": "Se digitalizó el proceso tal cual, con algunas mejoras puntuales."}, {"id": "b", "texto": "Se revisó el proceso con el negocio antes de construir y se simplificó."}, {"id": "c", "texto": "Nada, es lo mismo en una pantalla distinta."}, {"id": "d", "texto": "Se eliminó algún paso menor, sin discusión previa."}, {"id": "e", "texto": "Se rediseñó el proceso con el negocio, se midió el antes y el después y se documentó el cambio."}]'::jsonb),
  ('q073', 4, 14, 'Después de una entrega grande, los usuarios reportan errores. ¿Qué tan común es eso?', '[{"id": "a", "texto": "Frecuente, pero no se cuenta."}, {"id": "b", "texto": "Es lo normal, casi toda entrega trae errores."}, {"id": "c", "texto": "Se cuentan, son pocos y se analizan sus causas."}, {"id": "d", "texto": "Ocurre en algunas entregas y se corrigen con parches."}, {"id": "e", "texto": "Se miden por entrega, son pocos y la tendencia mejora."}]'::jsonb),
  ('q074', 4, 15, 'Un proceso del negocio claramente necesita cambiar antes de automatizarse. ¿Quién lidera ese cambio?', '[{"id": "a", "texto": "El negocio y TI lo rediseñan juntos antes de construir."}, {"id": "b", "texto": "El negocio lidera el rediseño y TI aporta capacidades, con metas de proceso medidas."}, {"id": "c", "texto": "Nadie, se automatiza como esté."}, {"id": "d", "texto": "El negocio lo describe y TI lo implementa, sin discusión."}, {"id": "e", "texto": "TI lo hace sola, sin conocer bien el proceso."}]'::jsonb),
  ('q075', 4, 16, 'Se prepara el lanzamiento de un sistema nuevo para cuarenta usuarios. ¿Qué acompaña a la entrega?', '[{"id": "a", "texto": "Solo el sistema, y un correo avisando."}, {"id": "b", "texto": "Un plan de adopción con metas, campeones por área y medición de uso tras el lanzamiento."}, {"id": "c", "texto": "Un plan con capacitación por perfil y seguimiento de uso."}, {"id": "d", "texto": "Una charla de una hora el día del lanzamiento."}, {"id": "e", "texto": "Un manual y una sesión de capacitación general."}]'::jsonb),
  ('q076', 4, 17, 'Llega un proyecto con requerimientos poco claros y otro con requerimientos muy estables. ¿Cómo se decide la manera de trabajarlos?', '[{"id": "a", "texto": "Igual para todos, por costumbre."}, {"id": "b", "texto": "Existe una guía que indica qué enfoque corresponde según el tipo de proyecto."}, {"id": "c", "texto": "Según el gusto del líder de cada proyecto."}, {"id": "d", "texto": "Se usan dos enfoques, pero sin una regla de cuándo uno u otro."}, {"id": "e", "texto": "La guía se aplica y se revisa con datos de qué enfoques funcionaron mejor."}]'::jsonb),
  ('q077', 4, 18, 'Se comparan las fechas y costos prometidos al empezar con los reales de proyectos ya cerrados. ¿Qué se ve?', '[{"id": "a", "texto": "Casi todos se pasaron, con diferencias grandes."}, {"id": "b", "texto": "Las desviaciones son pequeñas, estables y mejoran, y se usan para estimar mejor los siguientes."}, {"id": "c", "texto": "No se puede comparar, no se guardaron los datos originales."}, {"id": "d", "texto": "La mayoría se cumplió con desviaciones pequeñas y explicadas."}, {"id": "e", "texto": "Varios se pasaron en plazo o costo, con razones conocidas de algunos."}]'::jsonb),
  ('q078', 4, 19, 'A mitad de un proyecto se descubre que depende de un proveedor externo que se retrasó. ¿Qué se tenía previsto?', '[{"id": "a", "texto": "Nada, se improvisa."}, {"id": "b", "texto": "Alguien lo había mencionado de pasada."}, {"id": "c", "texto": "Una lista de riesgos hecha al inicio y nunca más revisada."}, {"id": "d", "texto": "Un registro vivo, con planes de respuesta y seguimiento, que se usa también en proyectos nuevos."}, {"id": "e", "texto": "Un registro de riesgos y dependencias revisado en cada hito."}]'::jsonb),
  ('q079', 4, 20, 'A mitad de proyecto el área pide agregar funciones que no estaban previstas. ¿Qué pasa?', '[{"id": "a", "texto": "Se aplica el proceso y se aprende de los cambios para estimar y definir mejor el alcance."}, {"id": "b", "texto": "Hay un proceso de control de cambios con impacto en plazo y costo documentado."}, {"id": "c", "texto": "TI protesta, pero termina haciéndolas."}, {"id": "d", "texto": "Se acuerdan cambios de forma verbal y luego se discuten."}, {"id": "e", "texto": "Se agregan, sin hablar de plazo ni costo."}]'::jsonb),
  ('q080', 4, 21, 'Un programador usa un asistente de IA para escribir parte de un sistema. ¿Qué reglas aplican a eso?', '[{"id": "a", "texto": "Las reglas se cumplen, se revisan periódicamente y hay evidencia de uso conforme a ellas."}, {"id": "b", "texto": "Hay una norma general, que no cubre el código ni los datos de la empresa."}, {"id": "c", "texto": "Hay herramientas aprobadas y reglas claras sobre datos y revisión."}, {"id": "d", "texto": "Ninguna, cada quien hace lo que quiere."}, {"id": "e", "texto": "Se sabe que algunos lo hacen, sin reglas escritas."}]'::jsonb),
  ('q081', 4, 22, 'Desde que se usa IA para programar, el equipo dice que va más rápido. ¿Qué dicen los datos de fallos?', '[{"id": "a", "texto": "No hay datos, solo la sensación del equipo."}, {"id": "b", "texto": "Hay más velocidad y los fallos se mantienen estables, con datos."}, {"id": "c", "texto": "Hay mejor velocidad, los fallos bajaron o siguen bajos y los datos cubren más de un periodo."}, {"id": "d", "texto": "Hay más entregas, y más errores, sin que se haya analizado."}, {"id": "e", "texto": "Hay más velocidad, y no se sabe qué pasó con los fallos."}]'::jsonb),
  ('q082', 4, 23, 'Se quiere que un asistente de IA ayude al equipo con la documentación y el código de la empresa. ¿Qué base técnica existe para que funcione bien?', '[{"id": "a", "texto": "Control de versiones, pruebas automáticas, documentación y políticas claras de acceso."}, {"id": "b", "texto": "Un repositorio común, pero con documentación casi inexistente."}, {"id": "c", "texto": "Todo lo anterior, más trabajo en lotes pequeños y una plataforma interna que asegura calidad de forma continua."}, {"id": "d", "texto": "Control de versiones y documentación parcial, sin acceso gobernado."}, {"id": "e", "texto": "Ninguna, el código está disperso y sin versionar."}]'::jsonb),
  ('q083', 5, 1, 'Un empleado nuevo quiere saber qué puede pedirle a TI, en qué horario y cuánto tarda. ¿Dónde lo averigua?', '[{"id": "a", "texto": "En un catálogo actualizado, que el negocio usa y TI revisa con base en los pedidos reales."}, {"id": "b", "texto": "En un correo de bienvenida con teléfonos y poco más."}, {"id": "c", "texto": "Preguntando a compañeros, no hay otro lugar."}, {"id": "d", "texto": "En una lista de servicios sin horarios ni responsables."}, {"id": "e", "texto": "En un catálogo con descripción, responsable, horario y criticidad de cada servicio."}]'::jsonb),
  ('q084', 5, 2, 'El sistema de pedidos se cae una hora y el negocio reclama. ¿Qué se había prometido de antemano?', '[{"id": "a", "texto": "Tiempos de respuesta definidos por TI, sin acuerdo con el negocio."}, {"id": "b", "texto": "Nada, no había compromiso alguno."}, {"id": "c", "texto": "Un acuerdo firmado con el negocio sobre disponibilidad y respuesta."}, {"id": "d", "texto": "Acuerdos firmados, con medición, reporte y revisión periódica entre ambas partes."}, {"id": "e", "texto": "Una promesa verbal de ''lo atendemos lo antes posible''."}]'::jsonb),
  ('q085', 5, 3, 'Se pregunta qué tan seguido se cumplió lo prometido en los servicios más importantes el último año. ¿Qué se responde?', '[{"id": "a", "texto": "Se midió en todos los críticos y se conocen los incumplimientos."}, {"id": "b", "texto": "Se midió, se reportó al negocio y los incumplimientos generaron acciones con resultado."}, {"id": "c", "texto": "Se cree que casi siempre, sin datos."}, {"id": "d", "texto": "No se midió."}, {"id": "e", "texto": "Se midió en algunos servicios, con huecos."}]'::jsonb),
  ('q086', 5, 4, 'Se pregunta a un gerente de operaciones cómo se definieron los tiempos de atención que hoy rigen. ¿Qué dice?', '[{"id": "a", "texto": "Los fijó TI y pidió una validación formal sin discusión."}, {"id": "b", "texto": "Se definieron en conjunto, mirando el impacto en el proceso."}, {"id": "c", "texto": "TI los fijó y se los comunicó después."}, {"id": "d", "texto": "No sabe que existen tiempos acordados."}, {"id": "e", "texto": "Se definieron en conjunto, se revisan cuando cambia el negocio y reflejan lo que realmente se necesita."}]'::jsonb),
  ('q087', 5, 5, 'Se pide un reporte de las fallas del último año: cuántas, qué tan graves y cuánto tardaron en resolverse. ¿Qué se entrega?', '[{"id": "a", "texto": "Un reporte por prioridad con tendencia y tiempos de resolución."}, {"id": "b", "texto": "Un reporte por prioridad, sin tendencia."}, {"id": "c", "texto": "Un total de tickets sin separar por gravedad."}, {"id": "d", "texto": "Un reporte con tendencia, tiempos y explicación de lo que se hizo para mejorar."}, {"id": "e", "texto": "No existe, los registros son incompletos."}]'::jsonb),
  ('q088', 5, 6, 'Se pregunta por la última caída grave de un servicio. ¿Qué se sabe de lo que costó?', '[{"id": "a", "texto": "Se recuerda que hubo una, sin más detalle."}, {"id": "b", "texto": "Se calcula para todos los incidentes mayores, y se usa para decidir inversiones en prevención."}, {"id": "c", "texto": "Se estimó el impacto en horas de proceso detenido."}, {"id": "d", "texto": "Se calculó el costo en horas y dinero con el área afectada."}, {"id": "e", "texto": "Se sabe cuánto duró, sin traducirlo al negocio."}]'::jsonb),
  ('q089', 5, 7, 'Un usuario reporta un problema, lo dan por resuelto y a los pocos días vuelve a aparecer. ¿Qué tan común es?', '[{"id": "a", "texto": "Se mide, se analiza cada reapertura y la proporción baja con el tiempo."}, {"id": "b", "texto": "Se mide y se mantiene dentro de un límite aceptado."}, {"id": "c", "texto": "Frecuente, y solo se sabe por las quejas."}, {"id": "d", "texto": "Muy común, y nadie lo mide."}, {"id": "e", "texto": "Se sabe que ocurre, sin una cifra."}]'::jsonb),
  ('q090', 5, 8, 'Un servicio crítico cae y cien personas preguntan qué pasa. ¿Cómo se comunica?', '[{"id": "a", "texto": "Un procedimiento con responsable, canales y mensajes tipo."}, {"id": "b", "texto": "Un procedimiento probado en simulacros, con aprendizajes incorporados en cada evento real."}, {"id": "c", "texto": "Cada quien se entera como puede."}, {"id": "d", "texto": "Algunos mensajes sueltos de quien se acuerde."}, {"id": "e", "texto": "Un aviso por correo, sin responsable definido."}]'::jsonb),
  ('q091', 5, 9, 'Hay una falla que ha aparecido cuatro veces en seis meses. ¿Qué se hizo después de la tercera vez?', '[{"id": "a", "texto": "Se identificó la causa y se corrigió de raíz."}, {"id": "b", "texto": "Alguien pensó en investigarla, sin llegar a hacerlo."}, {"id": "c", "texto": "Nada, se reinicia el servicio y se sigue."}, {"id": "d", "texto": "Se rastrean los incidentes recurrentes, se eliminan sus causas y la recurrencia cayó de forma medida."}, {"id": "e", "texto": "Se investigó una vez y se aplicó un parche temporal."}]'::jsonb),
  ('q092', 5, 10, 'Se pide el documento que explique por qué ocurrió la última caída grave. ¿Qué se encuentra?', '[{"id": "a", "texto": "Análisis de causa raíz de todos los incidentes mayores, con acciones verificadas."}, {"id": "b", "texto": "Un mensaje que dice ''ya se arregló''."}, {"id": "c", "texto": "Un informe corto del hecho, sin causa de fondo."}, {"id": "d", "texto": "Nada."}, {"id": "e", "texto": "Un análisis de causa raíz con acciones."}]'::jsonb),
  ('q093', 5, 11, 'Después de una caída se acordaron cinco acciones para que no se repita. Tres meses después, ¿cuántas se hicieron?', '[{"id": "a", "texto": "Casi todas dentro de plazo, con seguimiento visible para el negocio."}, {"id": "b", "texto": "La mayoría, dentro de plazo."}, {"id": "c", "texto": "Algunas, sin llevar la cuenta."}, {"id": "d", "texto": "No se sabe, nadie les dio seguimiento."}, {"id": "e", "texto": "Más o menos la mitad, con retrasos importantes."}]'::jsonb),
  ('q094', 5, 12, 'Un empleado nuevo llega el lunes y necesita su equipo, su correo y sus accesos. ¿Cuándo los tiene?', '[{"id": "a", "texto": "Semanas después, tras varios reclamos."}, {"id": "b", "texto": "El mismo día o el siguiente, si el pedido se hizo con antelación."}, {"id": "c", "texto": "Unos días, según cuánto insista su jefe."}, {"id": "d", "texto": "El primer día, con un proceso medido que se ha acortado con el tiempo."}, {"id": "e", "texto": "El primer día, con un procedimiento conocido."}]'::jsonb),
  ('q095', 5, 13, 'Se cierra una solicitud de soporte. ¿Qué pasa después con la opinión del usuario?', '[{"id": "a", "texto": "Nada, nadie pregunta."}, {"id": "b", "texto": "Se mide la satisfacción con buena respuesta y los resultados guían cambios en el servicio."}, {"id": "c", "texto": "Se envía una encuesta que casi nadie contesta."}, {"id": "d", "texto": "Se envía una encuesta con respuesta aceptable y se revisan los resultados negativos."}, {"id": "e", "texto": "Alguna vez se pregunta de palabra."}]'::jsonb),
  ('q096', 5, 14, 'Un usuario olvida su clave. ¿Cuántas personas y pasos necesita para recuperarla?', '[{"id": "a", "texto": "Llamar a TI y esperar a que alguien tenga tiempo."}, {"id": "b", "texto": "El autoservicio resuelve la mayoría de casos comunes y se mide qué porcentaje se resuelve al primer contacto."}, {"id": "c", "texto": "Un portal de autoservicio resuelve los casos comunes."}, {"id": "d", "texto": "Varias personas y días de espera."}, {"id": "e", "texto": "Llamar a TI y se resuelve en el momento durante el horario de oficina."}]'::jsonb),
  ('q097', 5, 15, 'Se pide exportar toda la información de solicitudes del último año. ¿Qué tan confiable es lo que sale?', '[{"id": "a", "texto": "Los datos son útiles pero tienen categorías confusas y huecos."}, {"id": "b", "texto": "Los datos son completos y categorizados de forma consistente."}, {"id": "c", "texto": "Los datos son confiables, se auditan y se usan en decisiones de mejora."}, {"id": "d", "texto": "No hay herramienta, solo correos y chats."}, {"id": "e", "texto": "Hay herramienta, pero la gente la evita y los datos están incompletos."}]'::jsonb),
  ('q098', 5, 16, 'Se necesita saber cuántos equipos y servidores tiene la empresa y quién responde por cada uno. ¿Cómo se averigua?', '[{"id": "a", "texto": "Con un inventario automatizado, conciliado de forma periódica con compras y bajas."}, {"id": "b", "texto": "Con un inventario vigente con dueño por activo."}, {"id": "c", "texto": "Contándolos uno por uno."}, {"id": "d", "texto": "Con un inventario parcial de equipos, sin servidores ni dueños."}, {"id": "e", "texto": "Con una hoja antigua que no refleja la realidad."}]'::jsonb),
  ('q099', 5, 17, 'Se publica una actualización urgente de seguridad. ¿Cuánto tarda en estar instalada en todos los equipos?', '[{"id": "a", "texto": "Semanas, con cobertura parcial."}, {"id": "b", "texto": "Pocos días, con cobertura medida y excepciones documentadas y justificadas."}, {"id": "c", "texto": "No se sabe cuántos la tienen."}, {"id": "d", "texto": "Pocos días, con control de cobertura."}, {"id": "e", "texto": "Meses, y solo en los equipos que alguien recuerde."}]'::jsonb),
  ('q100', 5, 18, 'Un servidor empieza a llenarse de datos y va a fallar en dos días. ¿Quién se entera primero?', '[{"id": "a", "texto": "Una alerta anticipada llega al responsable, y esos casos se registran para ajustar los umbrales."}, {"id": "b", "texto": "Los usuarios, cuando deja de funcionar."}, {"id": "c", "texto": "Una alerta llega al responsable del servicio con prioridad definida."}, {"id": "d", "texto": "Una alerta llega a un correo que se revisa a veces."}, {"id": "e", "texto": "Alguien que casualmente lo mira."}]'::jsonb),
  ('q101', 5, 19, 'El negocio planea duplicar sus ventas el próximo año. ¿Qué se hace en TI para que los sistemas lo soporten?', '[{"id": "a", "texto": "Se proyecta la demanda y se planifica la capacidad con el negocio."}, {"id": "b", "texto": "Se revisan algunas métricas cuando hay quejas."}, {"id": "c", "texto": "Nada, se espera ver qué pasa."}, {"id": "d", "texto": "Se proyecta de forma regular, se prueba la capacidad y los pronósticos se contrastan con lo ocurrido."}, {"id": "e", "texto": "Se confía en la experiencia de alguien del equipo."}]'::jsonb),
  ('q102', 5, 20, 'Alguien propone mejorar un proceso de soporte. ¿Dónde queda registrada esa idea?', '[{"id": "a", "texto": "En una lista informal sin dueño ni fecha."}, {"id": "b", "texto": "En la memoria de quien la propuso."}, {"id": "c", "texto": "En ningún sitio, se pierde."}, {"id": "d", "texto": "En un registro con dueño, fecha y efecto esperado."}, {"id": "e", "texto": "En un registro que se revisa y donde se verifica si el efecto esperado ocurrió."}]'::jsonb),
  ('q103', 5, 21, 'Se pregunta cuál fue la última mejora grande al servicio de soporte y qué cambió. ¿Qué se responde?', '[{"id": "a", "texto": "Mejoras continuas con efectos medidos y reconocidos por los usuarios."}, {"id": "b", "texto": "No se recuerda ninguna."}, {"id": "c", "texto": "Varias mejoras con datos de antes y después."}, {"id": "d", "texto": "Algunas mejoras con efectos percibidos."}, {"id": "e", "texto": "Una mejora menor, sin saber qué efecto tuvo."}]'::jsonb),
  ('q104', 5, 22, 'Se descubre que una tercera parte de las solicitudes de soporte son de lo mismo. ¿Qué se hace con eso?', '[{"id": "a", "texto": "Se analizan por categorías y se decide qué automatizar o eliminar de raíz."}, {"id": "b", "texto": "Nadie lo ve, porque nadie analiza los tickets."}, {"id": "c", "texto": "Se analiza de forma regular y se han eliminado categorías enteras de solicitudes con resultado medido."}, {"id": "d", "texto": "Alguien lo menciona y se sigue atendiendo igual."}, {"id": "e", "texto": "Se revisa a veces y se arreglan casos puntuales."}]'::jsonb),
  ('q105', 6, 1, 'El sistema central se cae un lunes por la mañana. ¿Qué tan claro está qué procesos se detienen y cuánto cuesta cada hora?', '[{"id": "a", "texto": "Hay un análisis con procesos críticos y costo estimado por hora de interrupción."}, {"id": "b", "texto": "No está claro, se descubre sobre la marcha."}, {"id": "c", "texto": "El análisis se actualiza con regularidad y Finanzas valida las cifras de impacto."}, {"id": "d", "texto": "Hay una lista de procesos críticos, sin estimar el costo."}, {"id": "e", "texto": "Se intuye cuáles son los más importantes, sin cifras."}]'::jsonb),
  ('q106', 6, 2, 'Se pregunta cuánto tiempo puede estar caído el sistema de facturación y cuánta información reciente se puede perder. ¿Qué se responde?', '[{"id": "a", "texto": "Hay metas por sistema, validadas con pruebas reales y revisadas cuando cambia el negocio."}, {"id": "b", "texto": "Hay metas definidas por sistema crítico."}, {"id": "c", "texto": "Nadie lo ha definido."}, {"id": "d", "texto": "Cada quien tiene una idea distinta."}, {"id": "e", "texto": "Hay metas generales para toda la infraestructura."}]'::jsonb),
  ('q107', 6, 3, 'TI promete restaurar un sistema en ocho horas. ¿Alguien del negocio sabe que ese es el compromiso?', '[{"id": "a", "texto": "El negocio revisó y aprobó los objetivos."}, {"id": "b", "texto": "Se les informó, sin pedir su opinión."}, {"id": "c", "texto": "No, es una decisión de TI que nadie conoce."}, {"id": "d", "texto": "El negocio los aprobó por escrito y los revisa cuando cambian sus procesos."}, {"id": "e", "texto": "Quizá, aunque nunca se confirmó."}]'::jsonb),
  ('q108', 6, 4, 'Un ataque cifra todos los servidores principales, incluidos los discos donde están las copias de seguridad. ¿Qué queda a salvo?', '[{"id": "a", "texto": "Copias externas, protegidas e independientes, con evidencia de que se verifican periódicamente."}, {"id": "b", "texto": "Copias en otro lugar, pero sin protección contra borrado."}, {"id": "c", "texto": "Nada, las copias estaban en el mismo lugar."}, {"id": "d", "texto": "Algunas copias antiguas, sin saber cuánto cubren."}, {"id": "e", "texto": "Copias externas y protegidas contra borrado para los sistemas críticos."}]'::jsonb),
  ('q109', 6, 5, 'Se pregunta cuándo fue la última vez que se recuperó un sistema desde una copia, de verdad, para probar que funciona. ¿Qué se responde?', '[{"id": "a", "texto": "Nunca se ha hecho."}, {"id": "b", "texto": "Se hace con regularidad, con tiempos medidos que mejoran o se mantienen dentro del objetivo."}, {"id": "c", "texto": "Hace mucho tiempo, sin registro del resultado."}, {"id": "d", "texto": "Hace más de un año, con resultado parcial."}, {"id": "e", "texto": "En el último año, con resultado y tiempo registrados."}]'::jsonb),
  ('q110', 6, 6, 'De los cinco sistemas más importantes de la empresa, ¿en cuántos se ha comprobado que la copia sirve?', '[{"id": "a", "texto": "En uno, sin una lista de los demás."}, {"id": "b", "texto": "En casi todos."}, {"id": "c", "texto": "En todos, con evidencia documentada y repetida."}, {"id": "d", "texto": "En dos o tres."}, {"id": "e", "texto": "En ninguno."}]'::jsonb),
  ('q111', 6, 7, 'Un incendio deja inutilizable el centro de datos principal. ¿Qué documento guía lo que hay que hacer?', '[{"id": "a", "texto": "Un plan vigente, probado en el último año y actualizado con lo aprendido."}, {"id": "b", "texto": "Ninguno, se improvisaría."}, {"id": "c", "texto": "Un documento antiguo que nadie recuerda dónde está."}, {"id": "d", "texto": "Un plan vigente, conocido y probado parcialmente."}, {"id": "e", "texto": "Un plan escrito que no se ha probado nunca."}]'::jsonb),
  ('q112', 6, 8, 'Se pregunta si alguna vez la empresa ensayó cómo operar sin sus sistemas principales. ¿Qué se responde?', '[{"id": "a", "texto": "Nunca."}, {"id": "b", "texto": "Una vez, y solo participó TI."}, {"id": "c", "texto": "Con regularidad, con participación del negocio, y las acciones se cierran dentro del plazo."}, {"id": "d", "texto": "Hace tiempo, con participación del negocio, sin seguimiento de lo encontrado."}, {"id": "e", "texto": "En los últimos dos años, con participación del negocio y con acciones definidas."}]'::jsonb),
  ('q113', 6, 9, 'El proveedor de internet de la sede principal queda sin servicio por un día. ¿Qué pasa con los sistemas críticos?', '[{"id": "a", "texto": "Se trabaja con celulares y soluciones improvisadas."}, {"id": "b", "texto": "Hay un alterno probado en conmutación real y la operación continúa con interrupción mínima."}, {"id": "c", "texto": "Todo se detiene hasta que regrese."}, {"id": "d", "texto": "Hay un sitio o servicio alterno para los sistemas críticos."}, {"id": "e", "texto": "Hay una alternativa para algunos servicios."}]'::jsonb),
  ('q114', 6, 10, 'Un proveedor del que depende la operación quiebra de un día para otro. ¿Qué hay preparado?', '[{"id": "a", "texto": "Nada, ni se sabía cuánto se depende de él."}, {"id": "b", "texto": "Se sabe que se depende, sin plan."}, {"id": "c", "texto": "Hay un plan documentado por cada dependencia crítica."}, {"id": "d", "texto": "Los planes se prueban y los contratos incluyen cláusulas de salida y continuidad."}, {"id": "e", "texto": "Se conocen las dependencias críticas y se piensa en alternativas."}]'::jsonb),
  ('q115', 6, 11, 'Se pregunta qué tan disponible estuvo el sistema más importante el último año y qué significó para el negocio. ¿Qué se responde?', '[{"id": "a", "texto": "Se midió contra lo acordado y se conoce el impacto de las caídas."}, {"id": "b", "texto": "Se cree que bien, sin datos."}, {"id": "c", "texto": "No se midió."}, {"id": "d", "texto": "Se midió con herramientas técnicas, sin traducirlo al impacto en el negocio."}, {"id": "e", "texto": "Se mide continuamente, se compara con lo acordado y con el impacto en el negocio, y mejora."}]'::jsonb),
  ('q116', 6, 12, 'Se pregunta qué una sola pieza que falle haría caer toda la operación: un equipo, un cable, una persona. ¿Qué se responde?', '[{"id": "a", "texto": "Hay una lista informal."}, {"id": "b", "texto": "Alguien menciona uno o dos de memoria."}, {"id": "c", "texto": "Hay un análisis documentado con plan para los principales."}, {"id": "d", "texto": "El análisis se actualiza y los puntos únicos de falla se reducen de forma comprobable."}, {"id": "e", "texto": "No se ha pensado."}]'::jsonb),
  ('q117', 6, 13, 'En la última interrupción importante, ¿cuánto tardó en volver todo a la normalidad y cómo se compara con lo prometido?', '[{"id": "a", "texto": "Mucho más de lo que se había prometido."}, {"id": "b", "texto": "Cerca de lo prometido, con registro por evento."}, {"id": "c", "texto": "Algo más de lo prometido, con diferencias importantes entre eventos."}, {"id": "d", "texto": "No se sabe, no se registró."}, {"id": "e", "texto": "Dentro de lo prometido en los últimos eventos, con registro y mejora sostenida."}]'::jsonb),
  ('q118', 6, 14, 'Ocurre una crisis un sábado a las tres de la mañana. ¿Cómo se localiza a las personas que deben actuar?', '[{"id": "a", "texto": "Con llamadas a quien se acuerde."}, {"id": "b", "texto": "Con una lista actualizada una vez, sin verificación."}, {"id": "c", "texto": "Con un árbol de comunicación vigente, con roles y contactos."}, {"id": "d", "texto": "Con un árbol vigente que se verifica con ejercicios y se corrige tras cada uno."}, {"id": "e", "texto": "Con una lista de teléfonos desactualizada."}]'::jsonb),
  ('q119', 6, 15, 'Los clientes no pueden hacer pedidos porque un sistema falló. ¿Qué se les dice y cuándo?', '[{"id": "a", "texto": "Mensajes improvisados, sin uniformidad."}, {"id": "b", "texto": "Nada hasta que reclaman."}, {"id": "c", "texto": "Un aviso general, tardío."}, {"id": "d", "texto": "Un protocolo probado y mejorado tras cada evento real."}, {"id": "e", "texto": "Un protocolo con mensajes por cada público y tiempos definidos."}]'::jsonb),
  ('q120', 6, 16, 'Pasado un mes de la última interrupción grave, ¿qué cambió en la empresa por ese aprendizaje?', '[{"id": "a", "texto": "Se cerraron las acciones y se verificó que reducen el impacto en eventos posteriores."}, {"id": "b", "texto": "Se habló del tema, sin cambios."}, {"id": "c", "texto": "Nada, se siguió igual."}, {"id": "d", "texto": "Se escribió un informe, sin acciones."}, {"id": "e", "texto": "Se definieron acciones con dueño y fecha, y la mayoría se cumplió."}]'::jsonb),
  ('q121', 7, 1, 'Un directivo pregunta: ''¿cuáles son los cinco mayores riesgos tecnológicos de la empresa y quién responde por cada uno?''. ¿Qué se contesta?', '[{"id": "a", "texto": "Se muestra una lista de riesgos, sin dueño ni tratamiento."}, {"id": "b", "texto": "Se muestra un registro con dueño, probabilidad, impacto y tratamiento."}, {"id": "c", "texto": "Se muestra un registro vivo, revisado con la gerencia, con riesgos que se cierran y otros que se agregan."}, {"id": "d", "texto": "No se sabría contestar con certeza."}, {"id": "e", "texto": "Se mencionan de memoria algunos riesgos, sin responsables."}]'::jsonb),
  ('q122', 7, 2, 'TI plantea adoptar una tecnología nueva con un riesgo moderado. ¿Cómo se decide si es aceptable?', '[{"id": "a", "texto": "Se discute en una reunión, sin referencia previa."}, {"id": "b", "texto": "Se compara con el nivel definido, y las excepciones se registran y se revisan."}, {"id": "c", "texto": "TI lo decide, y nadie del negocio opina."}, {"id": "d", "texto": "Por intuición de quien decide ese día."}, {"id": "e", "texto": "Se compara con un nivel de riesgo aceptable definido por la gerencia."}]'::jsonb),
  ('q123', 7, 3, 'Se detecta una amenaza seria un fin de semana. ¿A quién le toca decidir qué hacer?', '[{"id": "a", "texto": "No hay una persona definida."}, {"id": "b", "texto": "Un responsable nombrado, sin autoridad ni presupuesto."}, {"id": "c", "texto": "Alguien de infraestructura que hace lo que puede, además de su trabajo."}, {"id": "d", "texto": "Un responsable con autoridad definida, que reporta a un nivel directivo."}, {"id": "e", "texto": "Un responsable con autoridad, presupuesto y acceso directo a la gerencia, con resultados que presenta con regularidad."}]'::jsonb),
  ('q124', 7, 4, 'Se pregunta cuándo fue la última vez que la gerencia revisó los riesgos tecnológicos. ¿Qué se responde?', '[{"id": "a", "texto": "Nunca."}, {"id": "b", "texto": "Cada trimestre, con participación del negocio."}, {"id": "c", "texto": "Con regularidad fija, con datos, y con decisiones registradas en cada revisión."}, {"id": "d", "texto": "Una vez al año, solo con TI."}, {"id": "e", "texto": "Cuando ocurrió un problema."}]'::jsonb),
  ('q125', 7, 5, 'Una persona del equipo comercial copia una base de clientes a su computador personal. ¿Cómo se sabría?', '[{"id": "a", "texto": "Hay un inventario y una herramienta que alerta si los datos aparecen en lugares no autorizados."}, {"id": "b", "texto": "No se sabría."}, {"id": "c", "texto": "Solo si alguien lo comenta."}, {"id": "d", "texto": "Hay un inventario de datos sensibles con su ubicación autorizada."}, {"id": "e", "texto": "Se sabe dónde están las bases principales, sin saber si hay copias."}]'::jsonb),
  ('q126', 7, 6, 'Un empleado quiere compartir un archivo con un tercero. ¿Cómo sabe si puede hacerlo?', '[{"id": "a", "texto": "Hay una norma general que casi nadie conoce."}, {"id": "b", "texto": "Pregunta a su jefe, que decide por intuición."}, {"id": "c", "texto": "Decide él por su cuenta."}, {"id": "d", "texto": "La clasificación está en los sistemas y el control se aplica automáticamente."}, {"id": "e", "texto": "Hay clasificación definida y el empleado sabe qué puede compartir."}]'::jsonb),
  ('q127', 7, 7, 'Un proveedor con acceso a información de clientes sufre un ataque. ¿Qué se sabía de su nivel de seguridad?', '[{"id": "a", "texto": "Se evalúa con regularidad, se verifican sus controles y hay cláusulas contractuales aplicadas."}, {"id": "b", "texto": "Se pidió un cuestionario al contratar, sin revisarlo."}, {"id": "c", "texto": "Se evalúa a los críticos y se les exigen controles mínimos."}, {"id": "d", "texto": "Nada, nunca se evaluó."}, {"id": "e", "texto": "Se confió en su reputación."}]'::jsonb),
  ('q128', 7, 8, 'Se pide el reporte de fallas de seguridad conocidas que aún no se han corregido. ¿Qué se muestra?', '[{"id": "a", "texto": "Un escaneo regular, con hallazgos críticos corregidos en plazo."}, {"id": "b", "texto": "Un escaneo antiguo con cientos de hallazgos sin atender."}, {"id": "c", "texto": "Un escaneo reciente, con muchos hallazgos viejos sin plan."}, {"id": "d", "texto": "No existe, no se escanean."}, {"id": "e", "texto": "Un escaneo continuo, con antigüedad medida y hallazgos críticos prácticamente cerrados."}]'::jsonb),
  ('q129', 7, 9, 'Alguien obtiene la clave de un administrador mediante un engaño. ¿Qué lo detiene de entrar a los sistemas?', '[{"id": "a", "texto": "Todas las cuentas críticas y de acceso remoto exigen segundo factor."}, {"id": "b", "texto": "Algunos sistemas piden un segundo paso, otros no."}, {"id": "c", "texto": "Nada, con la clave entra."}, {"id": "d", "texto": "Todas lo exigen, se mide la cobertura y se bloquean las excepciones."}, {"id": "e", "texto": "Hay segundo factor en varias cuentas críticas, con excepciones desconocidas."}]'::jsonb),
  ('q130', 7, 10, 'Una persona que se fue de la empresa hace seis meses sigue con acceso a un sistema. ¿Cómo se habría detectado?', '[{"id": "a", "texto": "Por casualidad."}, {"id": "b", "texto": "En revisiones periódicas y con bajas automáticas desde Recursos Humanos."}, {"id": "c", "texto": "En una revisión anual, parcial."}, {"id": "d", "texto": "No se detectaría, a nadie se le ocurre revisar."}, {"id": "e", "texto": "En revisiones periódicas de accesos y de cuentas privilegiadas."}]'::jsonb),
  ('q131', 7, 11, 'Se pierde un computador portátil con información de clientes. ¿Qué tan expuesta queda esa información?', '[{"id": "a", "texto": "Algunos equipos están protegidos y otros no."}, {"id": "b", "texto": "Los equipos y los datos sensibles están cifrados."}, {"id": "c", "texto": "Totalmente, está disponible a quien lo encuentre."}, {"id": "d", "texto": "Todo está cifrado y se verifica la cobertura con informes periódicos."}, {"id": "e", "texto": "Probablemente, sin certeza."}]'::jsonb),
  ('q132', 7, 12, 'Un virus entra por un computador de la recepción. ¿Hasta dónde podría llegar?', '[{"id": "a", "texto": "A varias zonas, con algo de protección en los equipos."}, {"id": "b", "texto": "A toda la red, incluidos los servidores."}, {"id": "c", "texto": "A gran parte de la red, con poca protección."}, {"id": "d", "texto": "Queda contenido, es detectado rápido y hay pruebas de que la segmentación funciona."}, {"id": "e", "texto": "Queda contenido en su zona, con controles en los servidores."}]'::jsonb),
  ('q133', 7, 13, 'Llega un correo falso que parece de un proveedor y pide hacer clic en un enlace. ¿Qué haría la mayoría de la gente?', '[{"id": "a", "texto": "Hacer clic, no se les ha enseñado."}, {"id": "b", "texto": "La mayoría lo reportaría, según simulaciones realizadas."}, {"id": "c", "texto": "Una parte caería, y no se sabe cuántos."}, {"id": "d", "texto": "Muy pocos caerían, según simulaciones periódicas con resultados que mejoran."}, {"id": "e", "texto": "Se dio una charla una vez, sin medir resultados."}]'::jsonb),
  ('q134', 7, 14, 'A las tres de la madrugada alguien intenta entrar por fuerza bruta a un servidor. ¿Quién lo ve?', '[{"id": "a", "texto": "Nadie."}, {"id": "b", "texto": "Un equipo o servicio lo monitorea en horario ampliado."}, {"id": "c", "texto": "Un monitoreo continuo lo detecta y activa una respuesta documentada."}, {"id": "d", "texto": "Quizá lo vea alguien por la mañana si revisa los registros."}, {"id": "e", "texto": "Una herramienta lo registra, nadie la mira en tiempo real."}]'::jsonb),
  ('q135', 7, 15, 'Se confirma que alguien robó datos de clientes. ¿Qué guía lo que se hace en las primeras horas?', '[{"id": "a", "texto": "Un plan probado alguna vez con roles definidos."}, {"id": "b", "texto": "La experiencia de quien esté presente."}, {"id": "c", "texto": "Nada, se improvisa."}, {"id": "d", "texto": "Un documento sin probar."}, {"id": "e", "texto": "Un plan ensayado con regularidad, con ajustes tras cada ejercicio."}]'::jsonb),
  ('q136', 7, 16, 'Se pregunta cuánto tardó la empresa en darse cuenta del último incidente de seguridad y en detenerlo. ¿Qué se responde?', '[{"id": "a", "texto": "Se conocen algunos, sin tiempos medidos."}, {"id": "b", "texto": "No se sabe, ni si hubo alguno."}, {"id": "c", "texto": "Se registran incidentes con tiempo de detección y contención."}, {"id": "d", "texto": "Se enteraron de alguno por un tercero, mucho tiempo después."}, {"id": "e", "texto": "Los tiempos se miden, se comparan entre periodos y han mejorado."}]'::jsonb),
  ('q137', 7, 17, 'Tras un incidente, hay que decidir a quién avisar y cuándo. ¿Qué se tiene preparado?', '[{"id": "a", "texto": "Nada."}, {"id": "b", "texto": "Hay un procedimiento con responsables y plantillas."}, {"id": "c", "texto": "Se consultaría a un abogado en ese momento."}, {"id": "d", "texto": "Hay una idea general de a quién avisar."}, {"id": "e", "texto": "El procedimiento se ensayó y se coordina con el área legal."}]'::jsonb),
  ('q138', 7, 18, 'Un cliente grande exige demostrar que la empresa cumple ciertas normas de protección de datos. ¿Quién responde?', '[{"id": "a", "texto": "Hay un responsable, y se mantiene la evidencia de cumplimiento principal."}, {"id": "b", "texto": "Nadie sabe qué normas aplican."}, {"id": "c", "texto": "Hay un responsable, evidencia al día y revisiones periódicas con resultados documentados."}, {"id": "d", "texto": "Se sabe cuáles aplican, sin responsable claro."}, {"id": "e", "texto": "Cada área responde como puede."}]'::jsonb),
  ('q139', 7, 19, 'Un cliente pide saber qué datos suyos tiene la empresa y para qué los usa. ¿Cómo se responde?', '[{"id": "a", "texto": "Con una lista aproximada de dónde están sus datos."}, {"id": "b", "texto": "Con un registro que indica datos, finalidad y responsable."}, {"id": "c", "texto": "No se sabría contestar."}, {"id": "d", "texto": "Con una búsqueda manual en distintos sistemas."}, {"id": "e", "texto": "Con un registro actualizado y un proceso ya probado para responder estas solicitudes."}]'::jsonb),
  ('q140', 7, 20, 'Se pregunta si alguien externo ha intentado vulnerar los sistemas para probar su fortaleza. ¿Qué se responde?', '[{"id": "a", "texto": "Hace un tiempo, con parte de los hallazgos corregidos."}, {"id": "b", "texto": "En el último año, con hallazgos tratados."}, {"id": "c", "texto": "Nunca."}, {"id": "d", "texto": "Hace años, sin seguimiento."}, {"id": "e", "texto": "Con regularidad, y los hallazgos críticos se cierran en plazo y se verifican."}]'::jsonb),
  ('q141', 7, 21, 'Una persona del área financiera pega un contrato confidencial en una herramienta de IA pública para resumirlo. ¿Qué se sabe de eso?', '[{"id": "a", "texto": "Se conocen algunas herramientas usadas, sin control sobre los datos."}, {"id": "b", "texto": "Se sabe que pasa, sin cifras ni acción."}, {"id": "c", "texto": "Hay herramientas aprobadas y se conoce el uso de otras con reglas sobre datos."}, {"id": "d", "texto": "Nada, y se supondría que no ocurre."}, {"id": "e", "texto": "Hay inventario de uso, herramientas aprobadas accesibles y medición del uso no autorizado."}]'::jsonb),
  ('q142', 7, 22, 'Alguien intenta subir una base de clientes a un servicio externo de IA. ¿Qué lo detiene?', '[{"id": "a", "texto": "Nada."}, {"id": "b", "texto": "Controles técnicos que bloquean o alertan sobre datos sensibles."}, {"id": "c", "texto": "Su criterio personal."}, {"id": "d", "texto": "Una norma escrita que se confía a la buena voluntad."}, {"id": "e", "texto": "Controles técnicos con alertas revisadas y casos reales que demuestran su efectividad."}]'::jsonb),
  ('q143', 7, 23, 'Se va a poner en producción un asistente de IA que atiende a clientes. ¿Qué revisión se hace antes?', '[{"id": "a", "texto": "Ninguna, se publica."}, {"id": "b", "texto": "Una evaluación de riesgos documentada antes de la puesta en producción."}, {"id": "c", "texto": "Una evaluación documentada, con pruebas adversarias y monitoreo posterior."}, {"id": "d", "texto": "Una revisión técnica sin análisis de riesgos."}, {"id": "e", "texto": "Una prueba rápida de que responde bien."}]'::jsonb),
  ('q144', 7, 24, 'Un agente automatizado borra por error un archivo importante. ¿Cómo se reconstruye lo que hizo?', '[{"id": "a", "texto": "Con registros completos de las acciones del agente y permisos acotados."}, {"id": "b", "texto": "Con registros parciales de lo que hizo."}, {"id": "c", "texto": "Con registros completos, permisos mínimos revisados periódicamente y alertas ante acciones atípicas."}, {"id": "d", "texto": "No se podría, no hay registros."}, {"id": "e", "texto": "Preguntando a quien lo configuró."}]'::jsonb),
  ('q145', 8, 1, 'Se quiere cambiar un sistema y hay que saber con cuáles otros se conecta. ¿Dónde se averigua?', '[{"id": "a", "texto": "No hay forma, se descubre cuando algo deja de funcionar."}, {"id": "b", "texto": "En un mapa actualizado de forma continua que se consulta antes de cada cambio."}, {"id": "c", "texto": "En un mapa actualizado de aplicaciones e integraciones."}, {"id": "d", "texto": "Preguntando a la persona que lleva más años."}, {"id": "e", "texto": "En un diagrama antiguo que ya no refleja la realidad."}]'::jsonb),
  ('q146', 8, 2, 'El proceso de cierre contable del mes, ¿qué parte depende de que alguien copie datos entre archivos?', '[{"id": "a", "texto": "Prácticamente ninguna, y las pocas que existen están controladas y medidas."}, {"id": "b", "texto": "Una parte importante, con riesgo de errores frecuentes."}, {"id": "c", "texto": "Algunas etapas, con respaldo parcial."}, {"id": "d", "texto": "Casi todo, y solo lo entiende una persona."}, {"id": "e", "texto": "Pocas etapas, identificadas y con plan de eliminación."}]'::jsonb),
  ('q147', 8, 3, 'Dos equipos construyen soluciones parecidas con tecnologías distintas. ¿Quién lo habría evitado?', '[{"id": "a", "texto": "Un líder técnico, si se entera a tiempo."}, {"id": "b", "texto": "Hay estándares definidos y un rol que revisa su cumplimiento."}, {"id": "c", "texto": "Hay lineamientos generales que no siempre se siguen."}, {"id": "d", "texto": "Hay estándares, revisión sistemática y excepciones registradas con su justificación."}, {"id": "e", "texto": "Nadie, cada equipo hace lo que prefiere."}]'::jsonb),
  ('q148', 8, 4, 'Se necesita conectar un sistema nuevo con tres existentes. ¿Qué tan complicado es?', '[{"id": "a", "texto": "Hay conexiones directas entre sistemas, difíciles de mantener."}, {"id": "b", "texto": "La capa está documentada, es reutilizable y los equipos ya la usan sin pedir ayuda."}, {"id": "c", "texto": "Hay que construir cada conexión desde cero, con riesgos de romper otras."}, {"id": "d", "texto": "Hay una capa de integración con interfaces estándar para los sistemas principales."}, {"id": "e", "texto": "Hay algunas interfaces reutilizables y muchas a medida."}]'::jsonb),
  ('q149', 8, 5, 'Se pregunta cuántos sistemas de la empresa corren versiones que el fabricante ya no actualiza. ¿Qué se responde?', '[{"id": "a", "texto": "Hay una lista completa con riesgo evaluado."}, {"id": "b", "texto": "No se sabe."}, {"id": "c", "texto": "Hay una lista parcial, sin evaluar el riesgo."}, {"id": "d", "texto": "Hay una lista completa y su número baja de forma sostenida según el plan."}, {"id": "e", "texto": "Se sabe que hay varios, sin lista."}]'::jsonb),
  ('q150', 8, 6, 'Un desarrollador dice ''esto lo hicimos rápido y hay que arreglarlo''. ¿Dónde queda registrado ese pendiente?', '[{"id": "a", "texto": "En la memoria del equipo."}, {"id": "b", "texto": "En ningún lado, se acumula sin control."}, {"id": "c", "texto": "En un registro priorizado con presupuesto asignado, con avances verificables."}, {"id": "d", "texto": "En un registro de deuda técnica con estimación y plan de pago."}, {"id": "e", "texto": "En una lista informal, sin priorizar."}]'::jsonb),
  ('q151', 8, 7, 'Si se mira el presupuesto del último año, ¿cuánto se dedicó a renovar lo viejo y no solo a mantenerlo?', '[{"id": "a", "texto": "Nada."}, {"id": "b", "texto": "Una parte definida, sin continuidad entre años."}, {"id": "c", "texto": "Una parte protegida, con metas de modernización cumplidas y verificadas."}, {"id": "d", "texto": "Una parte mínima, cuando sobró dinero."}, {"id": "e", "texto": "Una parte definida y protegida en el presupuesto cada año."}]'::jsonb),
  ('q152', 8, 8, 'Un sistema muy antiguo sigue sosteniendo parte de la operación. ¿Quién lo conoce?', '[{"id": "a", "texto": "Está documentado y hay un plan de reemplazo con fecha."}, {"id": "b", "texto": "Dos personas, sin documentación."}, {"id": "c", "texto": "Un par de personas y documentación parcial."}, {"id": "d", "texto": "Varias personas, con documentación suficiente."}, {"id": "e", "texto": "Una sola persona, y no hay documentación."}]'::jsonb),
  ('q153', 8, 9, 'Hay un error en la información de un cliente en tres sistemas distintos. ¿Quién tiene autoridad para decidir cuál es el dato correcto?', '[{"id": "a", "texto": "Hay un responsable informal por tema, sin autoridad."}, {"id": "b", "texto": "Hay dueños de datos nombrados por cada dominio."}, {"id": "c", "texto": "Quien lo detecta lo corrige donde puede."}, {"id": "d", "texto": "Nadie, se discute entre áreas."}, {"id": "e", "texto": "Hay dueños que responden por la calidad y la reportan con indicadores."}]'::jsonb),
  ('q154', 8, 10, 'Se toma una muestra de cien clientes de la base. ¿Qué tan completos y sin duplicados están?', '[{"id": "a", "texto": "Se mide continuamente, con metas, y se previenen los errores en el origen."}, {"id": "b", "texto": "Se revisó una vez y se limpiaron los peores casos."}, {"id": "c", "texto": "Se mide la calidad con regularidad y se corrigen los problemas."}, {"id": "d", "texto": "Hay muchos duplicados y campos vacíos, y se tolera."}, {"id": "e", "texto": "No se sabe, nadie ha mirado."}]'::jsonb),
  ('q155', 8, 11, 'Dos gerentes presentan cifras distintas de ventas del mes, ambos con datos del sistema. ¿Qué ocurre?', '[{"id": "a", "texto": "Se discute cuál tiene razón y a menudo no se resuelve."}, {"id": "b", "texto": "Hay una fuente única, las diferencias casi no ocurren y se corrigen con un proceso definido."}, {"id": "c", "texto": "Se pide a TI que investigue, y tarda días."}, {"id": "d", "texto": "Hay una fuente oficial y las diferencias se explican por reglas conocidas."}, {"id": "e", "texto": "Se concilia a mano, y cada vez es un esfuerzo grande."}]'::jsonb),
  ('q156', 8, 12, 'Un analista nuevo necesita datos de ventas. ¿Cómo sabe dónde están, de dónde vienen y si puede usarlos?', '[{"id": "a", "texto": "Le pasan un archivo sin explicación de su origen."}, {"id": "b", "texto": "Hay un catálogo con origen de los datos y reglas de acceso."}, {"id": "c", "texto": "Hay una descripción parcial de las fuentes principales."}, {"id": "d", "texto": "Pregunta a todos hasta encontrar a alguien que sepa."}, {"id": "e", "texto": "Hay un catálogo vivo, con trazabilidad y accesos gobernados que se revisan."}]'::jsonb),
  ('q157', 8, 13, 'Una gerente quiere un dato que nunca ha pedido. ¿Cuánto tarda en tenerlo?', '[{"id": "a", "texto": "Horas o un día, con herramientas de consulta."}, {"id": "b", "texto": "Semanas o meses, si es que lo logra."}, {"id": "c", "texto": "Varias semanas, dependiendo de la disponibilidad de TI."}, {"id": "d", "texto": "Unos días, con ayuda de un analista."}, {"id": "e", "texto": "Minutos u horas, con autoservicio gobernado que ella misma puede usar."}]'::jsonb),
  ('q158', 8, 14, 'Se debe decidir dónde correr un sistema nuevo. ¿Cómo se toma la decisión?', '[{"id": "a", "texto": "Con criterios escritos de costo, riesgo y desempeño."}, {"id": "b", "texto": "Con criterios escritos, aplicados y revisados con datos de lo que resultó mejor."}, {"id": "c", "texto": "Según preferencia del proveedor o del técnico a cargo."}, {"id": "d", "texto": "Con una idea general, sin criterios escritos."}, {"id": "e", "texto": "Donde sea más rápido de montar."}]'::jsonb),
  ('q159', 8, 15, 'Se aproxima la temporada alta de ventas. ¿Cómo se sabe si los sistemas aguantarán?', '[{"id": "a", "texto": "Se revisan algunas métricas de uso actual."}, {"id": "b", "texto": "Se proyecta, se prueba bajo carga y se contrasta el resultado con lo que ocurrió."}, {"id": "c", "texto": "Por la experiencia de temporadas anteriores."}, {"id": "d", "texto": "Se proyecta la demanda y se compara con la capacidad."}, {"id": "e", "texto": "No se sabe, se espera a ver."}]'::jsonb),
  ('q160', 8, 16, 'La sede más importante tiene una caída de internet. ¿Qué tan seguido ocurre y cómo se mantiene la operación?', '[{"id": "a", "texto": "Se mide la disponibilidad, es alta y el respaldo ha sido probado."}, {"id": "b", "texto": "Es poco frecuente y hay respaldo de otro proveedor."}, {"id": "c", "texto": "Ocurre con frecuencia y detiene la operación."}, {"id": "d", "texto": "Ocurre de vez en cuando, con respaldo parcial."}, {"id": "e", "texto": "Ocurre a menudo y se trabaja con soluciones improvisadas."}]'::jsonb),
  ('q161', 8, 17, 'El único proveedor de nube de la empresa tiene una falla regional de varias horas. ¿Qué pasa?', '[{"id": "a", "texto": "Se detienen los sistemas principales, sin alternativa."}, {"id": "b", "texto": "Todo se detiene."}, {"id": "c", "texto": "Se detienen algunos servicios, y otros tienen respaldo."}, {"id": "d", "texto": "Hay un plan para continuar los servicios críticos desde otra región o proveedor."}, {"id": "e", "texto": "El plan está probado y la operación crítica sigue funcionando."}]'::jsonb),
  ('q162', 8, 18, 'Se quiere que un asistente de IA conteste preguntas con información interna de la empresa. ¿Qué tan listos están los datos?', '[{"id": "a", "texto": "Hay fuentes gobernadas, con calidad medida y trazabilidad de qué datos usó cada respuesta."}, {"id": "b", "texto": "Hay algunas fuentes ordenadas, con acceso aún sin gobernar."}, {"id": "c", "texto": "Hay fuentes confiables con acceso gobernado para casos prioritarios."}, {"id": "d", "texto": "No lo están, están dispersos y sin control."}, {"id": "e", "texto": "Hay mucha información, de calidad dudosa y sin permisos claros."}]'::jsonb),
  ('q163', 8, 19, 'Se aprueba un caso de IA que usará mucho cómputo. ¿Dónde se ejecutará y cuánto costará?', '[{"id": "a", "texto": "Hay una estrategia definida con estimación de costos por escenario."}, {"id": "b", "texto": "Hay una idea del servicio a usar y un costo aproximado."}, {"id": "c", "texto": "No se ha pensado, se verá en el momento."}, {"id": "d", "texto": "Se usará el servicio que haya a mano, sin estimación de costo."}, {"id": "e", "texto": "Hay una estrategia con modelo de costos que se contrasta con el consumo real."}]'::jsonb),
  ('q164', 8, 20, 'Un asistente de IA da una respuesta incorrecta a un cliente. ¿Cómo se investiga qué pasó?', '[{"id": "a", "texto": "Hay trazabilidad completa y monitoreo continuo con alertas de calidad."}, {"id": "b", "texto": "No se puede, no hay registro de qué respondió ni por qué."}, {"id": "c", "texto": "Hay registros de entradas, salidas y fuentes, y un entorno de prueba."}, {"id": "d", "texto": "Se reconstruye con lo que recuerde la persona."}, {"id": "e", "texto": "Hay registros de las respuestas, sin trazabilidad de los datos usados."}]'::jsonb),
  ('q165', 8, 21, 'Se quiere aplicar IA al proceso de pedidos, que corre sobre un sistema antiguo. ¿Qué pasa?', '[{"id": "a", "texto": "Los sistemas principales están preparados o en plan de modernización con fecha."}, {"id": "b", "texto": "Se podría con adaptaciones, aún no evaluadas."}, {"id": "c", "texto": "Se evaluó y hay un camino identificado, con tiempo y costo."}, {"id": "d", "texto": "Se podría con un esfuerzo muy grande, sin plan."}, {"id": "e", "texto": "Es imposible, el sistema no permite conectarse."}]'::jsonb),
  ('q166', 9, 1, 'Llega una persona nueva a TI y pregunta cuál es su rol y cuánto trabajo se espera que haga. ¿Qué se le muestra?', '[{"id": "a", "texto": "Un organigrama con roles definidos, sin relación con la carga real."}, {"id": "b", "texto": "Un organigrama con roles y una relación estimada entre carga y capacidad."}, {"id": "c", "texto": "Un organigrama sin descripciones de cargo."}, {"id": "d", "texto": "Nada, aprenderá sobre la marcha."}, {"id": "e", "texto": "Un organigrama actualizado, con carga y capacidad medidas y revisadas con regularidad."}]'::jsonb),
  ('q167', 9, 2, 'Se quiere saber cuántas personas hay en cada función de TI y si esa distribución tiene sentido. ¿Qué se muestra?', '[{"id": "a", "texto": "Una distribución que se ajusta con datos de carga y de plan, con decisiones recientes de reasignación."}, {"id": "b", "texto": "Una lista de nombres sin clasificación por función."}, {"id": "c", "texto": "No se sabe con precisión."}, {"id": "d", "texto": "Una clasificación aproximada, sin comparar con la necesidad."}, {"id": "e", "texto": "Una distribución clara y contrastada con las necesidades del plan."}]'::jsonb),
  ('q168', 9, 3, 'La persona que administra las bases de datos renuncia mañana. ¿Qué pasa?', '[{"id": "a", "texto": "Hay un suplente capacitado y documentación."}, {"id": "b", "texto": "Una crisis, nadie más sabe hacerlo."}, {"id": "c", "texto": "Hay varios cubriendo el rol y un plan de traspaso que ya se ha usado con éxito."}, {"id": "d", "texto": "Hay un suplente parcial, con capacidades limitadas."}, {"id": "e", "texto": "Alguien intentará cubrirlo, con riesgo alto."}]'::jsonb),
  ('q169', 9, 4, 'El directorio pregunta si TI ha crecido más o menos que el resto de la empresa. ¿Qué se responde?', '[{"id": "a", "texto": "Una impresión general."}, {"id": "b", "texto": "Cifras del último año, sin historia."}, {"id": "c", "texto": "La relación, su evolución y cómo cambió el trabajo y los servicios a la par."}, {"id": "d", "texto": "No se sabe."}, {"id": "e", "texto": "La relación y su evolución en tres años, con explicación."}]'::jsonb),
  ('q170', 9, 5, 'El plan exige trabajar con datos e inteligencia artificial el próximo año. ¿Cómo se sabe si el equipo está preparado?', '[{"id": "a", "texto": "Se pregunta a los líderes de forma informal."}, {"id": "b", "texto": "La matriz se actualiza, guía la capacitación y la contratación, y se verifica su avance."}, {"id": "c", "texto": "Se tiene una lista de habilidades por persona, sin compararla con el plan."}, {"id": "d", "texto": "No se sabe, se asume que aprenderán."}, {"id": "e", "texto": "Existe una matriz de habilidades contrastada con las necesidades."}]'::jsonb),
  ('q171', 9, 6, 'Se pregunta cuánto se capacitó el equipo de TI en el último año. ¿Qué se responde?', '[{"id": "a", "texto": "Hubo un plan alineado con las brechas de habilidades, con horas medidas y aplicación comprobada en el trabajo."}, {"id": "b", "texto": "Casi nada, no hubo presupuesto ni tiempo."}, {"id": "c", "texto": "Algunos cursos por iniciativa personal."}, {"id": "d", "texto": "Hubo un plan, con horas medidas por persona."}, {"id": "e", "texto": "Hubo un plan, parcialmente cumplido."}]'::jsonb),
  ('q172', 9, 7, 'Un cliente exige personal con ciertas certificaciones para un contrato. ¿Qué se puede mostrar?', '[{"id": "a", "texto": "Hay listado y plan de renovación alineado a las necesidades de los contratos y del plan."}, {"id": "b", "texto": "Algunas personas tienen certificaciones, sin registro."}, {"id": "c", "texto": "Hay un listado, con algunas vencidas."}, {"id": "d", "texto": "Hay un listado vigente de certificaciones relevantes."}, {"id": "e", "texto": "No se sabe quién tiene qué."}]'::jsonb),
  ('q173', 9, 8, 'Se quiere lanzar un proyecto de IA. ¿Quién lo haría?', '[{"id": "a", "texto": "Nadie en la empresa, y tampoco hay proveedor identificado."}, {"id": "b", "texto": "Una persona curiosa, sin experiencia real."}, {"id": "c", "texto": "Un proveedor externo, sin que el equipo aprenda."}, {"id": "d", "texto": "Un equipo interno con habilidades demostradas y un plan para cerrar brechas con apoyo externo puntual."}, {"id": "e", "texto": "Un equipo interno con apoyo externo y traspaso de conocimiento."}]'::jsonb),
  ('q174', 9, 9, 'Se revisa cuántas personas de TI se fueron en los últimos dos años. ¿Qué se sabe?', '[{"id": "a", "texto": "Se mide la rotación y se conocen las causas principales."}, {"id": "b", "texto": "Se conoce el número, con razones de salida parciales."}, {"id": "c", "texto": "No se lleva registro, ni se sabe por qué se fueron."}, {"id": "d", "texto": "Se fueron varias personas clave, sin análisis."}, {"id": "e", "texto": "Se mide, se conocen las causas y las acciones tomadas redujeron la rotación."}]'::jsonb),
  ('q175', 9, 10, 'Se abre una vacante para un rol crítico de TI. ¿Cuánto tarda en estar ocupada?', '[{"id": "a", "texto": "Un tiempo conocido, con plan de cobertura temporal."}, {"id": "b", "texto": "Unos dos meses, con cobertura improvisada."}, {"id": "c", "texto": "Meses, y a veces nunca se cubre."}, {"id": "d", "texto": "Un tiempo medido y corto, con una reserva de candidatos y una cobertura interna ya ensayada."}, {"id": "e", "texto": "Varios meses, sin plan mientras tanto."}]'::jsonb),
  ('q176', 9, 11, 'Se pregunta cómo está el equipo de TI en cuanto a cansancio y carga. ¿Cómo se sabe?', '[{"id": "a", "texto": "No se sabe."}, {"id": "b", "texto": "Por el sentir del jefe, sin datos."}, {"id": "c", "texto": "Con datos de horas extra y guardias y una encuesta de clima."}, {"id": "d", "texto": "Con datos regulares, encuestas y acciones concretas cuyos efectos se miden."}, {"id": "e", "texto": "Por comentarios de pasillo."}]'::jsonb),
  ('q177', 9, 12, 'El responsable de TI se retira en un año. ¿Quién lo reemplazaría y cómo se prepara?', '[{"id": "a", "texto": "Hay un plan de sucesión con candidatos y desarrollo definido."}, {"id": "b", "texto": "No se ha pensado."}, {"id": "c", "texto": "Hay un candidato informal."}, {"id": "d", "texto": "Hay un plan con candidatos, preparación en curso y evidencia de sucesiones anteriores exitosas."}, {"id": "e", "texto": "Se piensa en alguien, sin decirle ni prepararlo."}]'::jsonb),
  ('q178', 9, 13, 'Se pide la lista de proveedores sin los cuales la operación de TI se detendría. ¿Qué se entrega?', '[{"id": "a", "texto": "No existe."}, {"id": "b", "texto": "Una lista actualizada con dependencia, riesgos y plan por proveedor."}, {"id": "c", "texto": "Una lista con criticidad, servicio y responsable."}, {"id": "d", "texto": "Una lista de memoria."}, {"id": "e", "texto": "Una lista parcial, sin criticidad."}]'::jsonb),
  ('q179', 9, 14, 'Un proveedor incumple varias veces el tiempo de respuesta prometido. ¿Qué ocurre?', '[{"id": "a", "texto": "Nada, nadie lleva la cuenta."}, {"id": "b", "texto": "Se registra, sin aplicar lo previsto en el contrato."}, {"id": "c", "texto": "Se mide, se aplican consecuencias y el desempeño se usa para renovar o cambiar de proveedor."}, {"id": "d", "texto": "Se mide y se aplican penalidades o planes de mejora definidos."}, {"id": "e", "texto": "Se le reclama, sin consecuencias."}]'::jsonb),
  ('q180', 9, 15, 'La empresa decide cambiar de proveedor. ¿Qué dice el contrato sobre llevarse sus datos y la transición?', '[{"id": "a", "texto": "No se ha revisado, podría haber problemas."}, {"id": "b", "texto": "Algunos contratos tienen cláusulas parciales."}, {"id": "c", "texto": "Los contratos críticos las tienen y se verificó que son aplicables en la práctica."}, {"id": "d", "texto": "Los contratos críticos tienen cláusulas claras de salida y devolución de datos."}, {"id": "e", "texto": "Se cree que no hay nada al respecto."}]'::jsonb),
  ('q181', 9, 16, 'Un proveedor crítico tiene problemas de calidad. ¿Quién de la empresa lo atiende y cada cuánto se reúnen?', '[{"id": "a", "texto": "Un responsable informal, con reuniones esporádicas."}, {"id": "b", "texto": "Un responsable nombrado, con reuniones periódicas y un plan de mejora con seguimiento."}, {"id": "c", "texto": "Nadie en particular, depende de quién llame."}, {"id": "d", "texto": "Un responsable nombrado, con reuniones periódicas."}, {"id": "e", "texto": "Quien tenga contacto, sin periodicidad."}]'::jsonb),
  ('q182', 9, 17, 'Se pide a tres áreas del negocio que describan en una frase cómo es trabajar con TI. ¿Qué dicen?', '[{"id": "a", "texto": "Depende de la persona con la que toque."}, {"id": "b", "texto": "Es colaborativo y TI entiende lo que necesitan."}, {"id": "c", "texto": "Es una asociación, con ejemplos recientes en que TI aportó ideas para su negocio."}, {"id": "d", "texto": "Es difícil, lento y distante."}, {"id": "e", "texto": "Es correcto, pero transaccional."}]'::jsonb),
  ('q183', 9, 18, 'Un área nueva del negocio necesita apoyo continuo de TI. ¿Quién la acompaña?', '[{"id": "a", "texto": "Nadie en particular."}, {"id": "b", "texto": "Un contacto designado, que atiende varios temas."}, {"id": "c", "texto": "Un enlace asignado, con participación en las decisiones del área y resultados reconocidos por ella."}, {"id": "d", "texto": "Quien esté libre cuando se le pida."}, {"id": "e", "texto": "Un enlace de TI asignado con presencia regular en el área."}]'::jsonb),
  ('q184', 9, 19, 'TI y un área discrepan sobre quién tiene la responsabilidad por un sistema que falló. ¿Cómo se resuelve?', '[{"id": "a", "texto": "Se escala al más alto nivel después de meses de discusión."}, {"id": "b", "texto": "El mecanismo se usa, se resuelve con rapidez y las lecciones cambian los acuerdos de trabajo."}, {"id": "c", "texto": "Se evita el tema hasta que se olvida."}, {"id": "d", "texto": "Se negocia caso por caso, con desgaste."}, {"id": "e", "texto": "Hay un mecanismo definido para escalar y decidir."}]'::jsonb),
  ('q185', 10, 1, 'Se paga un sistema para cien personas. ¿Cuántas lo usan realmente en una semana normal?', '[{"id": "a", "texto": "Se cree que pocas, por los comentarios."}, {"id": "b", "texto": "No se sabe, nadie lo mide."}, {"id": "c", "texto": "Se mide el uso con regularidad, es alto y se actúa cuando baja."}, {"id": "d", "texto": "Se conoce una cifra aproximada de algunos sistemas."}, {"id": "e", "texto": "Se mide el uso de los principales y la mayoría de los licenciados lo usa."}]'::jsonb),
  ('q186', 10, 2, 'Un sistema tiene muchas funciones. ¿Cuántas se usan realmente?', '[{"id": "a", "texto": "Se sabe que una minoría se usa, sin detalle."}, {"id": "b", "texto": "Se mide el uso de funciones principales y se decide qué retirar o promover."}, {"id": "c", "texto": "Se mide, se promueve el uso de funciones valiosas y se retiran las que no aportan."}, {"id": "d", "texto": "Se conocen algunas funciones sin uso."}, {"id": "e", "texto": "Se desconoce."}]'::jsonb),
  ('q187', 10, 3, 'Se pregunta a un supervisor si, además del sistema oficial, lleva sus propios archivos para hacer su trabajo. ¿Qué responde?', '[{"id": "a", "texto": "Sí, para varias tareas importantes."}, {"id": "b", "texto": "Sí, para algunas tareas puntuales."}, {"id": "c", "texto": "Sí, el sistema oficial casi no se usa."}, {"id": "d", "texto": "No, y existen mediciones que lo confirman."}, {"id": "e", "texto": "Casi no, solo para casos excepcionales."}]'::jsonb),
  ('q188', 10, 4, 'Se pregunta por un sistema nuevo que hoy casi nadie usa. ¿Qué se cuenta?', '[{"id": "a", "texto": "Hay varios, y nadie sabe por qué."}, {"id": "b", "texto": "Hay alguno, y se culpa al usuario."}, {"id": "c", "texto": "Se identificó la causa y se tomó una acción correctiva."}, {"id": "d", "texto": "Se analizan sistemáticamente los casos y se corrigió el proceso de entrega para evitar repetirlos."}, {"id": "e", "texto": "Hay alguno, con razones identificadas sin acción."}]'::jsonb),
  ('q189', 10, 5, 'Se prepara un cambio que afectará la forma de trabajar de varias áreas. ¿Qué se prepara además de la tecnología?', '[{"id": "a", "texto": "Un plan con metas de adopción y revisión, que ajusta lo que se hace según los resultados."}, {"id": "b", "texto": "Una comunicación y alguna capacitación puntual."}, {"id": "c", "texto": "Un correo informativo."}, {"id": "d", "texto": "Un plan de cambio con comunicación, capacitación y seguimiento."}, {"id": "e", "texto": "Nada, se avisa cuando ya está en marcha."}]'::jsonb),
  ('q190', 10, 6, 'Un cambio genera resistencia en un área. ¿Quién del negocio se hace presente para respaldarlo?', '[{"id": "a", "texto": "Nadie, TI queda sola."}, {"id": "b", "texto": "Un patrocinador comprometido con metas propias de adopción, cuyo desempeño se evalúa por ellas."}, {"id": "c", "texto": "Un patrocinador nominal, con poca presencia."}, {"id": "d", "texto": "Un gerente que lo aprobó, que no vuelve a aparecer."}, {"id": "e", "texto": "Un patrocinador visible que comunica y resuelve obstáculos."}]'::jsonb),
  ('q191', 10, 7, 'Antes de un cambio, un usuario tiene dudas y miedos. ¿Dónde puede expresarlos?', '[{"id": "a", "texto": "En sesiones y canales previstos, y sus comentarios se registran."}, {"id": "b", "texto": "En una reunión informativa, con poco espacio para opinar."}, {"id": "c", "texto": "En ningún lado."}, {"id": "d", "texto": "Con su jefe, que rara vez lo transmite."}, {"id": "e", "texto": "En canales previstos, y sus comentarios producen ajustes visibles al cambio."}]'::jsonb),
  ('q192', 10, 8, 'Un área recibe cinco cambios tecnológicos en el mismo trimestre. ¿Cómo se gestiona?', '[{"id": "a", "texto": "No se nota ni se considera."}, {"id": "b", "texto": "Se nota el cansancio, sin acción."}, {"id": "c", "texto": "Se coordina la agenda de cambios y se espacian."}, {"id": "d", "texto": "Se pide al área que se adapte."}, {"id": "e", "texto": "Se mide la carga de cambio por área y las decisiones de calendario la consideran."}]'::jsonb),
  ('q193', 10, 9, 'Se lanzó un sistema nuevo hace seis meses. ¿Cuántos de sus usuarios recibieron capacitación?', '[{"id": "a", "texto": "Una minoría, en una sesión única."}, {"id": "b", "texto": "La gran mayoría, con registro de asistencia."}, {"id": "c", "texto": "Más o menos la mitad, sin seguimiento."}, {"id": "d", "texto": "Ninguno de forma formal."}, {"id": "e", "texto": "Casi todos, con medición de lo aprendido y refuerzo posterior."}]'::jsonb),
  ('q194', 10, 10, 'Se pregunta a los jefes de área qué tan cómodo está su equipo con herramientas digitales nuevas. ¿Qué responden?', '[{"id": "a", "texto": "Que tienen un diagnóstico y un plan para las brechas."}, {"id": "b", "texto": "Que hay niveles muy dispares, sin diagnóstico."}, {"id": "c", "texto": "No lo saben."}, {"id": "d", "texto": "Que hay mucha resistencia y poca habilidad."}, {"id": "e", "texto": "Que tienen un diagnóstico, plan y avances medibles en el nivel de habilidades."}]'::jsonb),
  ('q195', 10, 11, 'Un usuario se atasca con un sistema a las cinco de la tarde. ¿Dónde busca ayuda?', '[{"id": "a", "texto": "En material de apoyo y en un campeón de su área."}, {"id": "b", "texto": "En material actual, con campeones por área que reportan dudas frecuentes para mejorar el sistema."}, {"id": "c", "texto": "En un manual desactualizado."}, {"id": "d", "texto": "En ninguna parte, espera al día siguiente."}, {"id": "e", "texto": "Le pregunta a un compañero que sepa."}]'::jsonb),
  ('q196', 10, 12, 'Se pregunta cuántos empleados usan a diario una herramienta de IA autorizada por la empresa. ¿Qué se sabe?', '[{"id": "a", "texto": "Hay una herramienta aprobada con uso bajo."}, {"id": "b", "texto": "Hay herramientas aprobadas y se mide el uso en un grupo importante."}, {"id": "c", "texto": "No se sabe, ni se ha preguntado."}, {"id": "d", "texto": "Se mide el uso, es amplio y se conocen las tareas donde produce resultados."}, {"id": "e", "texto": "Se sabe que algunos usan herramientas personales no autorizadas."}]'::jsonb),
  ('q197', 10, 13, 'Un empleado quiere usar IA para preparar un informe con datos de clientes. ¿Sabe qué debe y no debe hacer?', '[{"id": "a", "texto": "Recibió una charla única."}, {"id": "b", "texto": "Tiene una idea general por lo que lee."}, {"id": "c", "texto": "Recibió capacitación, se evalúa su aplicación y se refuerza cuando cambian las reglas."}, {"id": "d", "texto": "No, nadie le ha explicado."}, {"id": "e", "texto": "Recibió capacitación específica y conoce las reglas."}]'::jsonb),
  ('q198', 10, 14, 'Un área empezó a usar IA para atender consultas. ¿Cambió la manera de trabajar o solo se agregó un asistente encima?', '[{"id": "a", "texto": "Solo se agregó la herramienta, sin cambiar nada."}, {"id": "b", "texto": "Se ajustaron algunos pasos del proceso."}, {"id": "c", "texto": "El proceso rediseñado se mide, muestra mejoras y se replica en otras áreas."}, {"id": "d", "texto": "Se rediseñó el proceso con el área, definiendo qué hace la IA y qué la persona."}, {"id": "e", "texto": "Algunos la usan, el proceso sigue igual."}]'::jsonb),
  ('q199', 10, 15, 'Se revisa el presupuesto de IA del último año. ¿En qué se invirtió?', '[{"id": "a", "texto": "Una parte relevante en personas y cambio, con plan definido."}, {"id": "b", "texto": "Una parte relevante, planificada y vinculada a los resultados de adopción."}, {"id": "c", "texto": "Casi todo en tecnología, con alguna charla."}, {"id": "d", "texto": "Casi todo en licencias y tecnología."}, {"id": "e", "texto": "Una parte pequeña en capacitación."}]'::jsonb),
  ('q200', 10, 16, 'Se lanza un sistema nuevo. ¿Cómo se sabrá si fue un éxito en términos de uso?', '[{"id": "a", "texto": "Con indicadores de uso con meta y responsable."}, {"id": "b", "texto": "No se definió."}, {"id": "c", "texto": "Si nadie se queja."}, {"id": "d", "texto": "Con una idea general de que lo usen."}, {"id": "e", "texto": "Con indicadores de uso y de resultado, con meta, responsable y revisión periódica."}]'::jsonb),
  ('q201', 10, 17, 'Un sistema nuevo se adoptó bien. ¿Qué cambió en la forma de trabajar o en los resultados?', '[{"id": "a", "texto": "No se sabe."}, {"id": "b", "texto": "Cambios medidos, sostenidos y reconocidos en los resultados del negocio."}, {"id": "c", "texto": "La gente dice que es más cómodo."}, {"id": "d", "texto": "Algunos cambios de comportamiento observados, sin datos."}, {"id": "e", "texto": "Cambios medidos en comportamiento o resultados."}]'::jsonb),
  ('q202', 10, 18, 'Un sistema costoso lleva un año sin ser usado. ¿Quién tiene que dar explicaciones?', '[{"id": "a", "texto": "Nadie."}, {"id": "b", "texto": "El dueño de negocio, con consecuencias previstas y decisiones tomadas en casos anteriores."}, {"id": "c", "texto": "TI, porque lo construyó."}, {"id": "d", "texto": "El área que lo pidió, de forma informal."}, {"id": "e", "texto": "El dueño de negocio nombrado, con un plan para corregirlo."}]'::jsonb),
  ('q203', 11, 1, 'La gerencia pregunta qué quiere lograr la empresa con inteligencia artificial en los próximos dos años. ¿Qué se muestra?', '[{"id": "a", "texto": "Una lista de herramientas probadas, sin objetivo."}, {"id": "b", "texto": "Nada, se usa lo que va apareciendo."}, {"id": "c", "texto": "Una estrategia ligada a objetivos del negocio, con metas definidas."}, {"id": "d", "texto": "Una estrategia con metas medidas, con avances reportados a la gerencia."}, {"id": "e", "texto": "Un documento con intenciones generales, sin metas."}]'::jsonb),
  ('q204', 11, 2, 'Un área quiere lanzar un proyecto de IA. ¿A quién lo plantea y quién decide?', '[{"id": "a", "texto": "Al responsable de TI, que decide solo."}, {"id": "b", "texto": "A un comité con negocio, riesgo y TI, con un responsable nombrado."}, {"id": "c", "texto": "A un grupo informal de interesados."}, {"id": "d", "texto": "No hay a quién, lo hace por su cuenta."}, {"id": "e", "texto": "Al comité, que decide con criterios y hace seguimiento a lo aprobado."}]'::jsonb),
  ('q205', 11, 3, 'Un empleado propone usar una herramienta de IA para analizar datos de clientes. ¿Qué regla se aplica?', '[{"id": "a", "texto": "Lo que opine su jefe."}, {"id": "b", "texto": "Una política vigente con criterios claros de aprobación."}, {"id": "c", "texto": "Un comunicado general sin criterios concretos."}, {"id": "d", "texto": "Ninguna."}, {"id": "e", "texto": "Una política vigente, aplicada con registros de casos aprobados y rechazados."}]'::jsonb),
  ('q206', 11, 4, 'Se pregunta cuántas herramientas y proyectos de IA tiene hoy la empresa. ¿Qué se responde?', '[{"id": "a", "texto": "Se mencionan unos pocos de memoria."}, {"id": "b", "texto": "No se sabe."}, {"id": "c", "texto": "Hay un inventario completo de sistemas en uso y en piloto."}, {"id": "d", "texto": "Hay una lista parcial."}, {"id": "e", "texto": "Hay un inventario actualizado con dueño, riesgo, costo y estado de cada uno."}]'::jsonb),
  ('q207', 11, 5, 'De todas las iniciativas de IA lanzadas en dos años, ¿cuántas están hoy funcionando en la operación real?', '[{"id": "a", "texto": "Una proporción medida y creciente, con criterios claros para pasar de piloto a producción."}, {"id": "b", "texto": "Ninguna, o no se sabe."}, {"id": "c", "texto": "Una proporción conocida, con casos claramente en producción."}, {"id": "d", "texto": "Algunas, con proporción desconocida."}, {"id": "e", "texto": "Muy pocas frente a las iniciadas, sin un registro claro."}]'::jsonb),
  ('q208', 11, 6, 'Se pide el valor que ha generado la IA en la empresa. ¿Cómo viene sustentado?', '[{"id": "a", "texto": "Con estimaciones optimistas de los responsables."}, {"id": "b", "texto": "Con afirmaciones generales."}, {"id": "c", "texto": "Con estimaciones por caso, sin verificar."}, {"id": "d", "texto": "Con valores medidos en la mayoría de casos y estimados claramente identificados."}, {"id": "e", "texto": "Con valores medidos y confirmados por Finanzas y por las áreas usuarias."}]'::jsonb),
  ('q209', 11, 7, 'Un piloto de IA no dio los resultados esperados. ¿Qué pasó con él?', '[{"id": "a", "texto": "Detener pilotos es parte del proceso y lo aprendido mejoró la selección de casos nuevos."}, {"id": "b", "texto": "Se detuvo con una decisión explícita y un aprendizaje documentado."}, {"id": "c", "texto": "Se abandonó en silencio."}, {"id": "d", "texto": "Sigue vivo sin que nadie lo revise."}, {"id": "e", "texto": "Se detuvo, sin analizar qué se aprendió."}]'::jsonb),
  ('q210', 11, 8, 'Hay veinte ideas de IA y recursos para tres. ¿Cómo se eligen?', '[{"id": "a", "texto": "Las que más entusiasmo generen."}, {"id": "b", "texto": "Con criterios de valor, factibilidad, riesgo y datos disponibles."}, {"id": "c", "texto": "Las que parezcan más fáciles."}, {"id": "d", "texto": "Las que proponga alguien con influencia."}, {"id": "e", "texto": "Con criterios aplicados y revisados según los resultados que dieron los casos elegidos."}]'::jsonb),
  ('q211', 11, 9, 'Se va a usar IA para pre-seleccionar candidatos o aprobar créditos. ¿Qué análisis previo se hace?', '[{"id": "a", "texto": "Se confía en el proveedor."}, {"id": "b", "texto": "Una evaluación documentada, revisada por un comité y monitoreada después de la puesta en marcha."}, {"id": "c", "texto": "Una evaluación documentada de riesgo e impacto, incluida la parte ética."}, {"id": "d", "texto": "Una revisión técnica de que funciona."}, {"id": "e", "texto": "Ninguno."}]'::jsonb),
  ('q212', 11, 10, 'Un asistente de IA recomienda una acción importante. ¿Quién la revisa antes de ejecutarse?', '[{"id": "a", "texto": "Depende de quién esté mirando."}, {"id": "b", "texto": "Se revisa en algunos casos, sin regla clara."}, {"id": "c", "texto": "Las reglas se cumplen y se verifica con registros de las revisiones realizadas."}, {"id": "d", "texto": "Hay reglas claras sobre qué decisiones requieren revisión humana."}, {"id": "e", "texto": "Nadie, se ejecuta."}]'::jsonb),
  ('q213', 11, 11, 'Un asistente de IA lleva seis meses funcionando. ¿Cómo se sabe si sigue respondiendo bien?', '[{"id": "a", "texto": "Se confía en que los usuarios avisen."}, {"id": "b", "texto": "Se monitorea una muestra regular con medición de errores."}, {"id": "c", "texto": "No se sabe, nadie lo revisa."}, {"id": "d", "texto": "Se monitorea con indicadores, alertas y acciones correctivas ya aplicadas."}, {"id": "e", "texto": "Se revisan algunas respuestas de vez en cuando."}]'::jsonb),
  ('q214', 11, 12, 'Un cliente pregunta bajo qué marco de buenas prácticas gestiona la empresa su uso de IA. ¿Qué se responde?', '[{"id": "a", "texto": "Se adoptó un marco como referencia, con avance documentado."}, {"id": "b", "texto": "Ninguno, ni se conocen."}, {"id": "c", "texto": "Se conocen, sin ninguna acción."}, {"id": "d", "texto": "Se aplica un marco con evidencia verificable y una revisión interna o externa de su cumplimiento."}, {"id": "e", "texto": "Se está estudiando alguno."}]'::jsonb),
  ('q215', 11, 13, 'Un agente de IA puede crear pedidos y modificar clientes en un sistema. ¿Qué límites tiene y quién responde por él?', '[{"id": "a", "texto": "Tienen un responsable, con permisos más amplios de lo necesario."}, {"id": "b", "texto": "No se sabe qué agentes existen ni qué pueden hacer."}, {"id": "c", "texto": "Existen, con permisos amplios y sin responsable."}, {"id": "d", "texto": "Tienen permisos acotados, responsable nombrado y registro de acciones."}, {"id": "e", "texto": "Los permisos y acciones se revisan con regularidad, y se han corregido casos reales."}]'::jsonb),
  ('q216', 11, 14, 'Se pone un agente de IA a hacer un proceso que antes hacían tres personas. ¿Qué se cambió del proceso?', '[{"id": "a", "texto": "Se ajustaron algunos pasos para que el agente funcione mejor."}, {"id": "b", "texto": "Se rediseñó, se midió el resultado antes y después y se aplicó el aprendizaje a otros procesos."}, {"id": "c", "texto": "Se eliminaron tareas obvias, sin revisión de fondo."}, {"id": "d", "texto": "Nada, el agente reproduce los mismos pasos."}, {"id": "e", "texto": "Se rediseñó el proceso para aprovechar lo que hace bien el agente y lo que hace la persona."}]'::jsonb),
  ('q217', 11, 15, 'Se quiere saber si un agente de IA realmente compensa. ¿Qué datos hay?', '[{"id": "a", "texto": "Ejemplos aislados de que funcionó."}, {"id": "b", "texto": "Datos de éxito, intervención humana y costo por tarea."}, {"id": "c", "texto": "Datos medidos de forma continua, comparados con el proceso anterior y usados para decidir si se escala."}, {"id": "d", "texto": "Datos parciales de tasa de éxito, sin costo."}, {"id": "e", "texto": "Ninguno, solo la impresión de que ayuda."}]'::jsonb),
  ('q218', 11, 16, 'Aparece una tecnología nueva que podría ser relevante. ¿Cómo se evalúa si vale la pena explorarla?', '[{"id": "a", "texto": "Alguien curioso la prueba en su tiempo libre."}, {"id": "b", "texto": "No se evalúa, se ignora o se adopta por moda."}, {"id": "c", "texto": "Se discute en una reunión, sin recursos asignados."}, {"id": "d", "texto": "Hay un mecanismo y presupuesto, con criterios para escalar o detener, y resultados registrados."}, {"id": "e", "texto": "Hay un mecanismo y un presupuesto de experimentación."}]'::jsonb),
  ('q219', 11, 17, 'Se pregunta cuál fue la última idea nueva que pasó de prueba a operación y qué produjo. ¿Qué se cuenta?', '[{"id": "a", "texto": "Ninguna."}, {"id": "b", "texto": "Una que se probó y se abandonó."}, {"id": "c", "texto": "Una en operación, sin beneficio medido."}, {"id": "d", "texto": "Una o más con beneficio medido."}, {"id": "e", "texto": "Varias, con beneficios sostenidos y reconocidos por el negocio."}]'::jsonb),
  ('q220', 11, 18, 'Se pregunta con quién fuera de la empresa se explora lo nuevo en tecnología. ¿Qué se responde?', '[{"id": "a", "texto": "Con alianzas activas, de las que han salido proyectos o capacidades concretas."}, {"id": "b", "texto": "Con alianzas definidas y objetivos de aprendizaje."}, {"id": "c", "texto": "Con proveedores, que presentan sus productos."}, {"id": "d", "texto": "Con algún proveedor o universidad, de manera esporádica."}, {"id": "e", "texto": "Con nadie."}]'::jsonb),
  ('q221', 11, 19, 'Un experimento lleva un año sin resultados claros. ¿Quién decide qué hacer con él y cómo?', '[{"id": "a", "texto": "Sigue, porque nadie se atreve a cerrarlo."}, {"id": "b", "texto": "Hay criterios definidos de continuar o detener, y se aplican."}, {"id": "c", "texto": "Se deja morir sin decisión."}, {"id": "d", "texto": "Los criterios se aplican, se registran las decisiones y se comparten las lecciones."}, {"id": "e", "texto": "Lo decide el responsable según su criterio."}]'::jsonb)
insert into public.biblioteca_acciones(pilar, horizonte, accion, indicador) values
  (1, 'quick_win', 'Nombrar un comité de TI y negocio con agenda mensual y acta de decisiones.', 'Actas de comité emitidas por mes'),
