  (3, '90_dias', 'Revisar contratos, licencias y nube para eliminar consumo ocioso o duplicado.', 'Ahorro anual identificado'),
  (3, '12_meses', 'Implantar economía unitaria (costo por usuario, transacción o servicio) con revisión trimestral.', 'Costo unitario por servicio y su tendencia'),
  (4, 'quick_win', 'Publicar un tablero de trabajo en curso con prioridades acordadas con el negocio.', 'Trabajo en curso por equipo'),
  (4, '90_dias', 'Medir tiempo de entrega y tasa de fallas en cambios, y fijar metas con el negocio.', 'Tiempo de entrega y tasa de fallas en cambios'),
  (4, '12_meses', 'Rediseñar el modelo de entrega por flujos de valor con automatización de pruebas y despliegue.', 'Frecuencia de despliegue y tiempo de entrega'),
  (5, 'quick_win', 'Publicar el catálogo de servicios con horarios, canales y tiempos de respuesta.', 'Servicios con acuerdo de nivel publicado (%)'),
  (5, '90_dias', 'Instituir gestión de problemas con análisis de causa raíz para incidentes repetidos.', 'Incidentes repetidos por mes'),
  (5, '12_meses', 'Implantar mejora continua del servicio con encuesta de experiencia y revisión de acuerdos de nivel.', 'Satisfacción del usuario y cumplimiento de acuerdos'),
  (6, 'quick_win', 'Probar la restauración de los respaldos de los sistemas críticos y registrar el resultado.', 'Restauraciones probadas con éxito (%)'),
  (6, '90_dias', 'Realizar el análisis de impacto en el negocio y fijar objetivos de tiempo y punto de recuperación.', 'Sistemas críticos con objetivos de recuperación aprobados (%)'),
  (6, '12_meses', 'Implantar y probar el plan de continuidad y recuperación ante desastres con ejercicios anuales.', 'Ejercicios de recuperación superados'),
  (7, 'quick_win', 'Activar doble factor de autenticación en correo, accesos remotos y cuentas privilegiadas.', 'Cuentas privilegiadas con doble factor (%)'),
  (7, '90_dias', 'Inventariar activos, datos sensibles y proveedores críticos, y revisar accesos privilegiados.', 'Activos críticos inventariados (%)'),
  (7, '12_meses', 'Implantar un programa de gestión de riesgo tecnológico con detección, respuesta y pruebas periódicas.', 'Tiempo de detección y de respuesta a incidentes'),
  (8, 'quick_win', 'Documentar el mapa de aplicaciones e integraciones críticas con su dueño.', 'Aplicaciones críticas documentadas (%)'),
  (8, '90_dias', 'Cuantificar la deuda técnica y priorizar su reducción con el negocio.', 'Deuda técnica priorizada con plan'),
  (8, '12_meses', 'Implantar gobierno de datos con dueños, calidad medida y acceso controlado, base para la IA.', 'Datos críticos con dueño y calidad medida (%)'),
  (9, 'quick_win', 'Mapear capacidades y cargas del equipo de TI, internas y externas.', 'Personas con carga mayor a la sostenible'),
  (9, '90_dias', 'Definir plan de desarrollo de habilidades y revisar desempeño de proveedores clave contra contrato.', 'Proveedores evaluados contra acuerdo de nivel (%)'),
  (9, '12_meses', 'Rediseñar la estructura de TI y el modelo de abastecimiento según la estrategia.', 'Rotación voluntaria y cobertura de roles críticos'),
  (10, 'quick_win', 'Medir el uso real de los sistemas entregados en los últimos 12 meses.', 'Usuarios activos frente a licenciados (%)'),
  (10, '90_dias', 'Incorporar gestión del cambio y capacitación en cada proyecto desde su inicio.', 'Proyectos con plan de cambio (%)'),
  (10, '12_meses', 'Implantar medición de adopción y beneficios por área con responsables del negocio.', 'Adopción y beneficio por área'),
  (11, 'quick_win', 'Inventariar los usos de IA actuales, incluidos los no autorizados, y publicar reglas básicas de uso.', 'Usos de IA inventariados'),
  (11, '90_dias', 'Definir gobierno de IA con portafolio de casos de uso priorizados por valor y riesgo.', 'Casos de uso con dueño y métrica de valor'),
  (11, '12_meses', 'Escalar los casos de IA con valor demostrado, con controles de riesgo y plataforma de datos lista.', 'Valor anual atribuible a casos de IA')
